def _semantic_sha256_json(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')).hexdigest()

def _validated_dataset_template(dataset_id, value, declared_sha256, approved_field_ids):
    if not isinstance(value, dict) or not _DATASET_TEMPLATE_REQUIRED_KEYS <= set(value) <= _DATASET_TEMPLATE_KEYS or (not re.fullmatch('[0-9a-f]{64}', str(declared_sha256 or ''))) or (_semantic_sha256_json(value) != declared_sha256):
        raise ValueError('Approved dataset template contract or hash is invalid.')
    encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    if not encoded or len(encoded) > 32 * 1024:
        raise ValueError('Approved dataset template exceeds the bounded payload size.')
    forbidden_keys = {'code', 'source', 'source_code', 'module', 'module_path', 'import_path', 'python', 'sql', 'url', 'uri', 'credential', 'secret', 'password', 'token', 'api_key', 'config_ref', 'query_ref', 'source_type', 'source_adapter', 'fields', 'family'}
    forbidden_values = ('http://', 'https://', 'mongodb://', 'mongodb+srv://', 'select ', 'insert ', 'update ', 'delete ', 'import ', 'e' + 'xec(', 'e' + 'val(', 'password', 'secret', 'token=', 'api_key')

    def visit(current, depth=0):
        if depth > 20:
            raise ValueError('Approved dataset template nesting is too deep.')
        if isinstance(current, dict):
            if len(current) > 512:
                raise ValueError('Approved dataset template object is too large.')
            for raw_key, child in current.items():
