    if not isinstance(detail_fields, list) or len(detail_fields) > 128 or len(detail_fields) != len(set(detail_fields)) or any((item not in approved_fields for item in detail_fields)) or (not isinstance(value.get('display_name'), str)) or (not 1 <= len(value['display_name']) <= 200) or (not isinstance(value.get('time_scope'), str)) or (not 1 <= len(value['time_scope']) <= 64) or (not isinstance(value.get('parameters'), dict)) or (len(value['parameters']) > 128) or (not isinstance(value.get('date_policy'), dict)) or (len(value['date_policy']) > 32) or (not isinstance(read_policy, dict)) or (set(read_policy) - {'read_only', 'timeout_seconds', 'max_rows'}) or (read_policy.get('read_only') is not True) or isinstance(read_policy.get('timeout_seconds'), bool) or (not isinstance(read_policy.get('timeout_seconds'), int)) or (not 1 <= read_policy['timeout_seconds'] <= 120) or isinstance(read_policy.get('max_rows'), bool) or (not isinstance(read_policy.get('max_rows'), int)) or (not 1 <= read_policy['max_rows'] <= 1000000):
        raise ValueError('Approved dataset template policies are invalid.')
    if 'date_filter_contract' in value and (not isinstance(value['date_filter_contract'], dict) or len(value['date_filter_contract']) > 32):
        raise ValueError('Approved dataset template date filter is invalid.')
    if 'fixture_only' in value and (not isinstance(value['fixture_only'], bool)):
        raise ValueError('Approved dataset template fixture policy is invalid.')
    if 'upstream_bindings' in value and (not isinstance(value['upstream_bindings'], list) or len(value['upstream_bindings']) > 64 or any((not isinstance(card, dict) for card in value['upstream_bindings']))):
        raise ValueError('Approved dataset template upstream bindings are invalid.')
    return deepcopy(value)

def _validated_semantic_templates(value, semantic_vocabulary):
    expected_root = {'contract_version', 'locale', 'timezone', 'planner_policy', *_SEMANTIC_TEMPLATE_SECTIONS, 'aliases'}
    if not isinstance(value, dict) or set(value) != expected_root:
        raise ValueError('Approved semantic templates root contract is invalid.')
    if value.get('contract_version') != 'metadata.authoring.semantic-templates.v1':
        raise ValueError('Approved semantic templates version is invalid.')
    encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')
    if not encoded or len(encoded) > 128 * 1024:
        raise ValueError('Approved semantic templates exceed the bounded payload size.')
    locale = value.get('locale')
    timezone = value.get('timezone')
    if not isinstance(locale, str) or not 1 <= len(locale) <= 64 or (not isinstance(timezone, str)) or (not 1 <= len(timezone) <= 128):
        raise ValueError('Approved semantic template locale or timezone is invalid.')
    planner_policy = value.get('planner_policy')
    if not isinstance(planner_policy, dict):
        raise ValueError('Approved semantic template planner policy is invalid.')
    planner_profile = planner_policy.get('planner_profile')
    if planner_profile == 'generic_v2':
        if set(planner_policy) != {'planner_profile'}:
            raise ValueError('Generic planner policy contains an unknown key.')
    elif planner_profile == 'legacy_v1_compat':
        if set(planner_policy) != {'planner_profile', 'legacy_catalog_sha256'} or not re.fullmatch('[0-9a-f]{64}', str(planner_policy.get('legacy_catalog_sha256') or '')):
            raise ValueError('Legacy planner policy pin is invalid.')
    else:
        raise ValueError('Approved semantic template planner profile is invalid.')
    forbidden_keys = {'source_type', 'source_adapter', 'config_ref', 'query_ref', 'physical_column', 'physical_aliases', 'coercion', 'credential', 'credentials', 'password', 'secret', 'api_key', 'token', 'code', 'python', 'script', 'sql'}
    forbidden_values = ('http://', 'https://', 'mongodb://', 'mongodb+srv://', 'select ', 'insert ', 'update ', 'delete ', 'import pandas', 'def ', 'lambda ', 'api_key', 'password', 'secret', 'token=')
    forbidden_value_patterns = (re.compile('(?:https?|mongodb(?:\\+srv)?|jdbc)://', re.IGNORECASE), re.compile('\\b(?:select\\s+.+\\s+from|insert\\s+into|delete\\s+from|update\\s+.+\\s+set)\\b', re.IGNORECASE), re.compile('\\b(?:import\\s+[A-Za-z_]|from\\s+[A-Za-z_][A-Za-z0-9_.]*\\s+import|def\\s+[A-Za-z_]\\w*\\s*\\(|lambda\\s+)'))

    def validate_safe_json(current, path=()):
        if len(path) > 24:
            raise ValueError('Approved semantic templates exceed the nesting depth limit.')
        if isinstance(current, dict):
            if len(current) > 8192 or any((str(key).casefold() in forbidden_keys for key in current)):
                raise ValueError('Approved semantic templates contain a forbidden execution key.')
            for key, child in current.items():
                if not isinstance(key, str) or not key or len(key) > 256:
                    raise ValueError('Approved semantic template key is invalid.')
                validate_safe_json(child, (*path, key))
            return
        if isinstance(current, list):
            if len(current) > 8192:
                raise ValueError('Approved semantic template array is too large.')
            for index, child in enumerate(current):
                validate_safe_json(child, (*path, str(index)))
            return
        if current is None or isinstance(current, (bool, int, float)):
            return
        if isinstance(current, str):
            folded = current.casefold()
            if not current or len(current) > 4096 or any((fragment in folded for fragment in forbidden_values)) or any((pattern.search(current) for pattern in forbidden_value_patterns)):
                raise ValueError('Approved semantic templates contain a forbidden execution value.')
            return
        raise ValueError('Approved semantic templates contain a non-JSON value.')
    vocabulary_ids = {section: {str(card['id']) for card in (semantic_vocabulary or {}).get(section) or [] if isinstance(card, dict) and isinstance(card.get('id'), str)} for section in _SEMANTIC_TEMPLATE_SECTIONS}
    normalized = {'contract_version': 'metadata.authoring.semantic-templates.v1', 'locale': locale, 'timezone': timezone, 'planner_policy': deepcopy(planner_policy)}
    for section in _SEMANTIC_TEMPLATE_SECTIONS:
        cards = value.get(section)
        identity_key, allowed_keys, section_limit = _SEMANTIC_TEMPLATE_SPECS[section]
        if not isinstance(cards, dict) or len(cards) > min(_SEMANTIC_VOCABULARY_LIMITS[section][1], section_limit) or set(cards) != vocabulary_ids[section]:
            raise ValueError(f'Approved semantic template {section} IDs do not match the vocabulary.')
        for item_id, card in cards.items():
            if not re.fullmatch('[A-Za-z][A-Za-z0-9_.-]{0,127}', str(item_id)) or not isinstance(card, dict) or identity_key in card or (not set(card).issubset(allowed_keys - {identity_key})):
                raise ValueError(f'Approved semantic template {section} card is open or invalid.')
        validate_safe_json(cards, (section,))
        normalized[section] = {str(item_id): cards[item_id] for item_id in sorted(cards)}
    registered_families = {str(card.get('family') or '') for card in (semantic_vocabulary or {}).get('datasets') or [] if isinstance(card, dict)}
    field_families = {str(card.get('id') or ''): set(card.get('families') or []) for card in (semantic_vocabulary or {}).get('fields') or [] if isinstance(card, dict)}
    for metric in normalized['metrics'].values():
        binding = metric.get('source_binding')
        if binding is None:
            continue
        if not isinstance(binding, dict) or not {'dataset_family', 'field'}.issubset(binding) or (not set(binding).issubset({'dataset_family', 'field', 'fixed_filters'})):
            raise ValueError('Approved metric source binding is open or incomplete.')
        family = str(binding.get('dataset_family') or '')
        field_id = str(binding.get('field') or '')
        if family not in registered_families or family not in field_families.get(field_id, set()):
            raise ValueError('Approved metric source binding is not registered.')
        fixed_filters = binding.get('fixed_filters', [])
        if not isinstance(fixed_filters, list) or len(fixed_filters) > 64:
            raise ValueError('Approved metric fixed filters are invalid.')
        for fixed_filter in fixed_filters:
            if not isinstance(fixed_filter, dict) or set(fixed_filter) != {'field', 'operator', 'semantic_type', 'value'} or family not in field_families.get(str(fixed_filter.get('field') or ''), set()):
                raise ValueError('Approved metric fixed filter is not registered.')

    def recipe_operations(current):
        operations = set()
        if isinstance(current, dict):
            operation = current.get('op')
            if isinstance(operation, str) and operation:
                operations.add(operation)
            for child in current.values():
                operations.update(recipe_operations(child))
        elif isinstance(current, list):
            for child in current:
                operations.update(recipe_operations(child))
        return operations
    allowed_recipe_ops = _SEMANTIC_TEMPLATE_LEGACY_RECIPE_OPS if planner_profile == 'legacy_v1_compat' else _SEMANTIC_TEMPLATE_GENERIC_RECIPE_OPS
    for recipe in normalized['recipes'].values():
        if not recipe_operations(recipe.get('default_operation_template')).issubset(allowed_recipe_ops):
            raise ValueError('Approved recipe is incompatible with the planner policy.')
    aliases = value.get('aliases')
    if not isinstance(aliases, dict) or not 1 <= len(aliases) <= 8192:
        raise ValueError('Approved semantic template aliases are invalid.')
    target_ids = {'dataset': {str(card.get('id') or '') for card in (semantic_vocabulary or {}).get('datasets') or [] if isinstance(card, dict)}, 'field': set(field_families), 'metric': set(normalized['metrics']), 'relation': set(normalized['relations']), 'grain': set(normalized['grains']), 'predicate': set(normalized['predicates']), 'recipe': set(normalized['recipes']), 'entity_group': set(normalized['entity_groups']), 'process_group': set(normalized['entity_groups']), 'product_group': set(normalized['predicates'])}
    process_targets = set()
    for ordering in normalized['orderings'].values():
        for item in ordering.get('items') or []:
            if isinstance(item, dict) and isinstance(item.get('oper_name'), str):
                process_targets.add(item['oper_name'])
    target_ids['process'] = process_targets
    allowed_alias_types = _SEMANTIC_TEMPLATE_LEGACY_ALIAS_TYPES if planner_profile == 'legacy_v1_compat' else _SEMANTIC_TEMPLATE_GENERIC_ALIAS_TYPES
    for alias_id, card in aliases.items():
        if not isinstance(alias_id, str) or not alias_id or len(alias_id) > 256 or (not isinstance(card, dict)) or (set(card) != {'target_type', 'target_key', 'values', 'normalization', 'match', 'conflict', 'provenance_source'}):
            raise ValueError('Approved semantic template alias card is invalid.')
        target_type = str(card.get('target_type') or '')
        target_key = str(card.get('target_key') or '')
        normalization = card.get('normalization')
        values = card.get('values')
        if alias_id != f'{target_type}:{target_key}' or target_type not in allowed_alias_types or (target_type != 'status' and target_key not in target_ids.get(target_type, set())) or (not isinstance(normalization, list)) or (not 1 <= len(normalization) <= 16) or (len(normalization) != len(set(normalization))) or any((not isinstance(item, str) or not re.fullmatch('[a-z][a-z0-9_]{0,63}', item) for item in normalization)) or any((not isinstance(card.get(key), str) or not card.get(key) or len(card.get(key)) > 128 for key in ('match', 'conflict', 'provenance_source'))) or (not isinstance(values, list)) or (not 1 <= len(values) <= 128):
            raise ValueError('Approved semantic template alias policy is invalid.')
        for alias_value in values:
            if not isinstance(alias_value, dict) or set(alias_value) != {'text', 'priority'} or (not isinstance(alias_value.get('text'), str)) or (not alias_value.get('text')) or (len(alias_value.get('text')) > 256) or isinstance(alias_value.get('priority'), bool) or (not isinstance(alias_value.get('priority'), int)) or (not 0 <= alias_value.get('priority') <= 1000000):
                raise ValueError('Approved semantic template alias value is invalid.')
    validate_safe_json(aliases, ('aliases',))
    normalized['aliases'] = {str(alias_id): aliases[alias_id] for alias_id in sorted(aliases)}
    return normalized

def _authoring_schema_refs(value):
    refs = set()
    if isinstance(value, dict):
        raw_ref = value.get('$ref')
        prefix = '#/$defs/'
        if isinstance(raw_ref, str) and raw_ref.startswith(prefix):
            refs.add(raw_ref[len(prefix):])
        for child in value.values():
            refs.update(_authoring_schema_refs(child))
    elif isinstance(value, list):
        for child in value:
            refs.update(_authoring_schema_refs(child))
    return refs

def _authoring_reachable_defs(properties, available_defs):
    pending = set(_authoring_schema_refs(properties))
    selected = {}
    while pending:
        name = sorted(pending)[0]
        pending.remove(name)
        if name in selected:
            continue
        definition = available_defs.get(name)
        if not isinstance(definition, dict):
            raise ContractError('metadata_schema_error', 'metadata_prompt_context', 'Schema definition reference is missing.', {'definition': name})
        selected[name] = deepcopy(definition)
        pending.update(_authoring_schema_refs(definition) - set(selected))
    return {name: selected[name] for name in sorted(selected)}

def _authoring_partial_schema(value):
    if isinstance(value, list):
        return [_authoring_partial_schema(child) for child in value]
    if not isinstance(value, dict):
        return deepcopy(value)
    result = {key: _authoring_partial_schema(child) for key, child in value.items() if key != 'required'}
    raw_type = result.get('type')
    if raw_type == 'object' or (isinstance(raw_type, list) and 'object' in raw_type):
        current_min = result.get('minProperties')
        result['minProperties'] = max(1, int(current_min) if isinstance(current_min, int) else 0)
    return result

def _authoring_output_schema(kind, *, annotation_only=False, proposal_source_sha256='', bootstrap_fragment=False, approved_dataset_ids=(), approved_dataset_field_ids=None, approved_semantic_vocabulary=None):
    if kind == 'domain' and annotation_only:
        return load_schema('metadata-annotation-proposal.schema.json')
    full_schema = load_schema('metadata-authoring-draft.schema.json')
    if kind == 'domain' and (not bootstrap_fragment):
        draft_schema = full_schema
    elif kind == 'domain' and bootstrap_fragment:
        if approved_semantic_vocabulary is None:
            draft_schema = load_schema('metadata-freeform-domain-ir.schema.json')
        else:
            draft_schema = load_schema('metadata-annotation-proposal.schema.json')
    elif kind == 'dataset':
        if bootstrap_fragment and approved_semantic_vocabulary is None:
            draft_schema = load_schema('metadata-freeform-dataset-ir.schema.json')
        else:
            draft_schema = load_schema('metadata-bootstrap-dataset-ir.schema.json')
    elif kind == 'main_filter':
        draft_schema = load_schema('metadata-freeform-main-filter-ir.schema.json' if bootstrap_fragment and approved_semantic_vocabulary is None else 'metadata-bootstrap-main-filter-ir.schema.json')
        if approved_semantic_vocabulary is not None:
            draft_schema = _apply_main_filter_ir_allowlists(draft_schema, approved_semantic_vocabulary)
    else:
        sections = {'domain': ('display_name', 'description', 'locale', 'timezone', 'metrics', 'relations', 'aliases', 'entity_groups', 'grains', 'orderings', 'predicates', 'recipes'), 'dataset': ('datasets', 'aliases'), 'main_filter': ('aliases',)}.get(kind) if bootstrap_fragment else {'dataset': ('datasets',), 'main_filter': ('aliases', 'entity_groups', 'grains', 'orderings', 'predicates', 'recipes')}.get(kind)
        if sections is None:
            return {}
        owned = {section: deepcopy(full_schema['properties'][section]) for section in sections}
        draft_schema = {'$schema': full_schema.get('$schema'), 'title': f'metadata.authoring.{kind}.section-patch.v1', 'type': 'object', 'additionalProperties': False, 'minProperties': 1, 'maxProperties': len(sections), 'properties': deepcopy(owned) if bootstrap_fragment else _authoring_partial_schema(owned), '$defs': _authoring_reachable_defs(owned, full_schema.get('$defs') or {}) if bootstrap_fragment else _authoring_partial_schema(_authoring_reachable_defs(owned, full_schema.get('$defs') or {}))}
        if kind == 'domain' and bootstrap_fragment:
            draft_schema['required'] = ['display_name']
        elif kind == 'dataset':
            draft_schema['required'] = ['datasets']
        elif kind == 'main_filter' and bootstrap_fragment:
            draft_schema['required'] = ['aliases']
    approved_ids = sorted({str(item).strip() for item in approved_dataset_ids or () if str(item).strip()})
    if kind == 'dataset' and approved_ids:
        if 'datasetCard' in (draft_schema.get('$defs') or {}):
            field_allowlists = {dataset_id: sorted({str(field_id).strip() for field_id in (approved_dataset_field_ids or {}).get(dataset_id) or [] if str(field_id).strip()}) for dataset_id in approved_ids}
            if any((not field_ids for field_ids in field_allowlists.values())):
                raise ContractError('metadata_dependency_error', 'metadata_prompt_context', '승인 dataset별 field allowlist가 비어 있습니다.')
            base_dataset_card = deepcopy(draft_schema['$defs']['datasetCard'])
            base_field_card = deepcopy(draft_schema['$defs']['fieldCard'])
            dataset_branches = []
            for dataset_id in approved_ids:
                allowed_fields = field_allowlists[dataset_id]
                dataset_card = deepcopy(base_dataset_card)
                dataset_card['properties']['dataset_id'] = {'type': 'string', 'enum': [dataset_id]}
                field_card = deepcopy(base_field_card)
                field_card['properties']['id'] = {'type': 'string', 'enum': allowed_fields}
                field_card['properties']['col'] = {'type': 'string', 'enum': allowed_fields}
                dataset_card['properties']['fields']['items'] = field_card
                dataset_branches.append(dataset_card)
            draft_schema['$defs']['datasetCard'] = {'oneOf': dataset_branches}
        else:
            draft_schema['properties']['datasets']['propertyNames'] = {'enum': approved_ids}
    source_sha256 = str(proposal_source_sha256 or '').strip()
    if not source_sha256:
        return draft_schema
    proposal_schema = deepcopy(load_schema('metadata-authoring-proposal.schema.json'))
    draft_definitions = {}
    proposal_definitions = proposal_schema.setdefault('$defs', {})
    if set(draft_definitions) & set(proposal_definitions):
        raise ContractError('metadata_schema_error', 'metadata_prompt_context', '등록 초안 schema definition 이름이 proposal 계약과 충돌합니다.')
    proposal_definitions.update(draft_definitions)
    for branch in proposal_schema.get('oneOf') or []:
        if not isinstance(branch, dict):
            continue
        properties = branch.get('properties')
        required = branch.get('required')
        if not isinstance(properties, dict) or not isinstance(required, list):
            continue
        properties['source_sha256'] = {'type': 'string', 'const': source_sha256, 'description': '입력 원문의 결정론적 SHA-256. runtime_context 값을 그대로 복사합니다.'}
        if 'source_sha256' not in required:
            required.append('source_sha256')
        status = (properties.get('status') or {}).get('const')
        if status == 'complete':
            properties['draft'] = deepcopy(draft_schema)
    return proposal_schema

def _authoring_alias_only_manifest_patch(source_manifest):
    counts = source_manifest.get('counts') if isinstance(source_manifest, dict) else None
    inventories = source_manifest.get('inventories') if isinstance(source_manifest, dict) else None
    if not isinstance(counts, dict) or not isinstance(inventories, dict):
        return None
    non_alias_kinds = ('datasets', 'fields', 'field_bindings', 'field_roles', 'metrics', 'grains', 'grain_keys', 'grain_display_fields', 'relations', 'relation_endpoints', 'relation_keys', 'relation_policies', 'recipes', 'operations')
    if any((int(counts.get(item) or 0) != 0 for item in non_alias_kinds)):
        return None
    bindings = inventories.get('alias_bindings')
    if int(counts.get('aliases') or 0) < 1 or not isinstance(bindings, list):
        return None
    aliases = {}
    for binding in bindings:
        if not isinstance(binding, dict) or set(binding) != {'alias', 'target'}:
            return None
        alias = binding.get('alias')
        target = binding.get('target')
        if not isinstance(alias, str) or not alias or (not isinstance(target, str)) or (not target):
            return None
        if alias in aliases and aliases[alias] != target:
            return None
        aliases[alias] = target
    return {'aliases': {key: aliases[key] for key in sorted(aliases)}}

def _freeform_source_manifest(source_text):
    source_sha256 = hashlib.sha256(source_text.encode('utf-8')).hexdigest()
    inventories = {'datasets': [], 'dataset_fields': {}, 'fields': [], 'field_roles': {}, 'metrics': [], 'grains': [], 'grain_keys': {}, 'grain_display_fields': {}, 'relations': [], 'relation_endpoints': {}, 'relation_keys': {}, 'relation_policies': {}, 'recipes': [], 'operations': [], 'aliases': [], 'alias_targets': [], 'alias_bindings': []}
    counts = {'datasets': 0, 'fields': 0, 'field_bindings': 0, 'field_roles': 0, 'metrics': 0, 'grains': 0, 'grain_keys': 0, 'grain_display_fields': 0, 'relations': 0, 'relation_endpoints': 0, 'relation_keys': 0, 'relation_policies': 0, 'recipes': 0, 'operations': 0, 'aliases': 0, 'alias_targets': 0, 'alias_bindings': 0}
    material = {'contract_version': 'metadata.authoring.source-manifest.v1', 'source_sha256': source_sha256, 'inventories': inventories, 'required_sections': [], 'counts': counts}
    material['manifest_sha256'] = hashlib.sha256(json.dumps(material, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
    return material

class AuthoringPromptContextBuilder(Component):
    display_name = '메타데이터 등록 프롬프트 컨텍스트'
