            raise ContractError('metadata_schema_error', 'metadata_prompt_context', '메타데이터 TXT는 1~65536 UTF-8 바이트여야 합니다.')
        grounding_mode = str(getattr(self, 'source_grounding_mode', 'freeform_llm') or 'freeform_llm').strip()
