                semantic_vocabulary = _validated_semantic_vocabulary(reference_context.get('semantic_vocabulary'), expected_dataset_families=dataset_families, expected_field_families=field_families)
                semantic_templates = _validated_semantic_templates(reference_context.get('semantic_templates'), semantic_vocabulary)
            except ValueError as exc:
                raise ContractError('metadata_dependency_error', 'metadata_prompt_context', '승인 축약 의미 어휘가 유효하지 않습니다.') from exc
            if reference_context.get('contract_version') != 'metadata.authoring.source-registry-context.v3' or reference_context.get('domain_id') != str(getattr(self, 'domain_id', '') or '').strip() or (not isinstance(reference_context.get('bindings'), dict)) or (not isinstance(reference_context.get('dataset_descriptors'), dict)) or (set(reference_context.get('bindings') or {}) != set(reference_context.get('dataset_descriptors') or {})) or (reference_context.get('semantic_vocabulary') != semantic_vocabulary) or (reference_context.get('semantic_templates') != semantic_templates) or (reference_context.get('semantic_templates_sha256') != hashlib.sha256(json.dumps(semantic_templates, ensure_ascii=False, sort_keys=True, separators=(',', ':'), allow_nan=False).encode('utf-8')).hexdigest()) or any((not re.fullmatch('[0-9a-f]{64}', str(reference_context.get(key) or '')) for key in ('semantic_templates_blueprint_sha256', 'semantic_templates_executable_sha256', 'semantic_templates_projection_sha256'))) or (reference_context.get('registry_sha256') != expected_registry_sha256):
                raise ContractError('metadata_dependency_error', 'metadata_prompt_context', '승인 Source 참조 컨텍스트 hash 또는 도메인 결합이 유효하지 않습니다.')
        invoke = kind in {'domain', 'dataset'}
        if kind == 'main_filter' and strict_inventory:
            invoke = _authoring_alias_only_manifest_patch(source_manifest) is None
        elif kind == 'main_filter':
            invoke = True
        purpose = {'domain': 'metadata_domain_annotation' if annotation_only else 'metadata_domain_draft', 'dataset': 'metadata_dataset_draft', 'main_filter': 'metadata_main_filter_draft', 'domain_policy': 'metadata_domain_policy'}[kind]
        variables = {'authoring_kind': kind, 'domain_id': str(getattr(self, 'domain_id', '') or '').strip(), 'environment': str(getattr(self, 'environment', '') or '').strip(), 'source_grounding_mode': grounding_mode, 'source_text': source_text, 'source_sha256': str(source_manifest.get('source_sha256') or ''), 'source_manifest': source_manifest, 'bootstrap_fragment': bootstrap_fragment}
        approved_dataset_ids = sorted((str(card['id']) for card in (reference_context.get('semantic_vocabulary') or {}).get('datasets') or []))
        if reference_context and kind in {'domain', 'dataset', 'main_filter'}:
            variables['approved_semantic_vocabulary'] = deepcopy(reference_context['semantic_vocabulary'])
            variables['source_registry_sha256'] = str(reference_context.get('registry_sha256') or '')
        if invoke:
            variables['output_schema'] = _authoring_output_schema(kind, annotation_only=annotation_only, bootstrap_fragment=bootstrap_fragment, approved_dataset_ids=approved_dataset_ids, approved_dataset_field_ids=_dataset_field_allowlists_from_vocabulary(semantic_vocabulary, reference_context.get('dataset_descriptors')) if reference_context and kind == 'dataset' else None, approved_semantic_vocabulary=semantic_vocabulary if reference_context else None, proposal_source_sha256=str(source_manifest.get('source_sha256') or '') if grounding_mode == 'freeform_llm' and (not annotation_only) else '')
        if annotation_only:
            try:
