def _secret_text(value):
    if hasattr(value, 'get_secret_value'):
        value = value.get_secret_value()
    return str(value or '').strip()

MAX_AUTHORING_MODEL_RESPONSE_BYTES = 192 * 1024

def _json_object(text):
    """Extract exactly one balanced, syntactically valid JSON object.

    Preamble, suffix text and Markdown fences are framing only. We never repair
    invalid escapes, single quotes, trailing commas, truncated JSON or multiple
    candidate objects.
    """
    if isinstance(text, dict):
        value = deepcopy(text)
        response_bytes = len(json.dumps(value, ensure_ascii=False, separators=(',', ':'), allow_nan=False).encode('utf-8'))
        if response_bytes > MAX_AUTHORING_MODEL_RESPONSE_BYTES:
            raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft exceeds the bounded response size.', {'response_bytes': response_bytes, 'max_bytes': MAX_AUTHORING_MODEL_RESPONSE_BYTES})
        return value
    raw = str(text or '').strip()
    response_bytes = len(raw.encode('utf-8'))
    if not raw or response_bytes > MAX_AUTHORING_MODEL_RESPONSE_BYTES:
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft response size is invalid.', {'response_bytes': response_bytes, 'max_bytes': MAX_AUTHORING_MODEL_RESPONSE_BYTES})
    spans = []
    start = None
    depth = 0
    in_string = False
    escaped = False
    for index, character in enumerate(raw):
        if start is None:
            if character == '{':
                start = index
                depth = 1
                in_string = False
                escaped = False
            elif character == '}':
                raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft JSON framing is unbalanced.', {'framing_reason': 'unmatched_closing_brace'})
            continue
        if in_string:
            if escaped:
                escaped = False
            elif character == '\\':
                escaped = True
            elif character == '"':
                in_string = False
            continue
        if character == '"':
            in_string = True
        elif character == '{':
            depth += 1
        elif character == '}':
            depth -= 1
            if depth == 0:
                spans.append((start, index + 1))
                start = None
    if start is not None:
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft JSON framing is incomplete.', {'framing_reason': 'unclosed_object'})
    if len(spans) != 1:
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft must contain exactly one JSON object.', {'object_count': len(spans)})
    prefix = raw[:spans[0][0]]
    suffix = raw[spans[0][1]:]
    if any((character in '[]' for character in prefix + suffix)):
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft JSON framing is invalid.', {'framing_reason': 'array_wrapper'})
    candidate = raw[spans[0][0]:spans[0][1]]
    try:
        value = json.loads(candidate)
    except json.JSONDecodeError as exc:
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft JSON is invalid.', {'line': exc.lineno, 'column': exc.colno}) from exc
    if not isinstance(value, dict):
        raise ContractError('metadata_schema_error', 'metadata_draft', 'LLM draft must be an object.')
    return value

def _strict_json_value(text, *, label, expected_type):
    raw = str(text or '').strip()
    if not raw:
        return None
    if raw.startswith('```'):
        raw = raw.split('\n', 1)[1] if '\n' in raw else ''
        raw = raw.rsplit('```', 1)[0].strip()
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ContractError('metadata_schema_error', 'metadata_policy_input', f'{label} must be valid JSON.', {'line': exc.lineno}) from exc
    if not isinstance(value, expected_type):
        expected = 'array' if expected_type is list else 'object'
        raise ContractError('metadata_schema_error', 'metadata_policy_input', f'{label} must be a JSON {expected}.')
    return value

