def _bootstrap_schema_refs(value):
    refs = set()
    if isinstance(value, dict):
        raw_ref = value.get('$ref')
        prefix = '#/$defs/'
        if isinstance(raw_ref, str) and raw_ref.startswith(prefix):
            refs.add(raw_ref[len(prefix):])
        for child in value.values():
            refs.update(_bootstrap_schema_refs(child))
    elif isinstance(value, list):
        for child in value:
            refs.update(_bootstrap_schema_refs(child))
    return refs

def _bootstrap_reachable_defs(properties, available_defs):
    pending = set(_bootstrap_schema_refs(properties))
    selected = {}
    while pending:
        name = sorted(pending)[0]
        pending.remove(name)
        if name in selected:
            continue
        definition = available_defs.get(name)
        if not isinstance(definition, dict):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '분할 초기 등록 schema definition 참조가 유효하지 않습니다.', {'definition': name})
        selected[name] = deepcopy(definition)
        pending.update(_bootstrap_schema_refs(definition) - set(selected))
    return {name: selected[name] for name in sorted(selected)}

def _bootstrap_partial_schema(value):
    if isinstance(value, list):
        return [_bootstrap_partial_schema(child) for child in value]
    if not isinstance(value, dict):
        return deepcopy(value)
    result = {key: _bootstrap_partial_schema(child) for key, child in value.items() if key != 'required'}
    raw_type = result.get('type')
    if raw_type == 'object' or (isinstance(raw_type, list) and 'object' in raw_type):
        current_min = result.get('minProperties')
        result['minProperties'] = max(1, int(current_min) if isinstance(current_min, int) else 0)
    return result

def _bootstrap_fragment_draft_schema(kind):
    sections = BOOTSTRAP_FRAGMENT_SECTIONS.get(kind)
    if sections is None:
        raise ContractError('metadata_schema_error', 'metadata_authoring', '분할 초기 등록 제안 종류가 유효하지 않습니다.', {'authoring_branch': str(kind or '')})
    if kind == 'domain':
        return load_schema('metadata-annotation-proposal.schema.json')
    if kind == 'dataset':
        return load_schema('metadata-bootstrap-dataset-ir.schema.json')
    if kind == 'main_filter':
        return load_schema('metadata-bootstrap-main-filter-ir.schema.json')
    full_schema = load_schema('metadata-authoring-draft.schema.json')
    owned = {section: deepcopy(full_schema['properties'][section]) for section in sections}
    return {'$schema': full_schema.get('$schema'), 'title': f'metadata.authoring.{kind}.section-patch.v1', 'type': 'object', 'additionalProperties': False, 'minProperties': 1, 'maxProperties': len(sections), 'properties': deepcopy(owned), '$defs': _bootstrap_reachable_defs(owned, full_schema.get('$defs') or {}), 'required': list(BOOTSTRAP_FRAGMENT_REQUIRED[kind])}

def _bootstrap_output_schema(kind, source_sha256, approved_dataset_ids=(), approved_dataset_field_ids=None, approved_semantic_vocabulary=None):
    proposal_schema = deepcopy(load_schema('metadata-authoring-proposal.schema.json'))
    draft_schema = _bootstrap_fragment_draft_schema(kind)
    if approved_semantic_vocabulary is None:
        if kind == 'domain':
            draft_schema = load_schema('metadata-freeform-domain-ir.schema.json')
        elif kind == 'dataset':
            draft_schema = load_schema('metadata-freeform-dataset-ir.schema.json')
        elif kind == 'main_filter':
            draft_schema = load_schema('metadata-freeform-main-filter-ir.schema.json')
    if kind == 'main_filter' and approved_semantic_vocabulary is not None:
        draft_schema = _apply_main_filter_ir_allowlists(draft_schema, approved_semantic_vocabulary)
    approved_ids = sorted({str(item).strip() for item in approved_dataset_ids or () if str(item).strip()})
    if kind == 'dataset' and approved_ids:
        field_allowlists = {dataset_id: sorted({str(field_id).strip() for field_id in (approved_dataset_field_ids or {}).get(dataset_id) or [] if str(field_id).strip()}) for dataset_id in approved_ids}
        if any((not field_ids for field_ids in field_allowlists.values())):
            raise ContractError('metadata_dependency_error', 'metadata_source_context', '승인 dataset별 field allowlist가 비어 있습니다.')
        base_dataset_card = deepcopy(draft_schema['$defs']['datasetCard'])
        base_field_card = deepcopy(draft_schema['$defs']['fieldCard'])
        dataset_branches = []
        for dataset_id in approved_ids:
            allowed_fields = field_allowlists[dataset_id]
            dataset_card = deepcopy(base_dataset_card)
            dataset_card['properties']['dataset_id'] = {'type': 'string', 'enum': [dataset_id]}
            field_card = deepcopy(base_field_card)
            field_card['properties']['id'] = {'type': 'string', 'enum': allowed_fields}
            field_card['properties']['col'] = {'type': 'string', 'enum': allowed_fields}
            dataset_card['properties']['fields']['items'] = field_card
            dataset_branches.append(dataset_card)
        draft_schema['$defs']['datasetCard'] = {'oneOf': dataset_branches}
    draft_definitions = {}
    proposal_definitions = proposal_schema.setdefault('$defs', {})
    if set(draft_definitions) & set(proposal_definitions):
        raise ContractError('metadata_schema_error', 'metadata_prompt_contract', '등록 초안 schema definition 이름이 proposal 계약과 충돌합니다.')
    proposal_definitions.update(draft_definitions)
    for branch in proposal_schema.get('oneOf') or []:
        properties = branch.get('properties') if isinstance(branch, dict) else None
        required = branch.get('required') if isinstance(branch, dict) else None
        if not isinstance(properties, dict) or not isinstance(required, list):
            continue
        properties['source_sha256'] = {'type': 'string', 'const': source_sha256}
        if 'source_sha256' not in required:
            required.append('source_sha256')
        if (properties.get('status') or {}).get('const') == 'complete':
            properties['draft'] = deepcopy(draft_schema)
    return proposal_schema

def _authoring_section_output_schema(kind, *, source_sha256, grounding_mode, annotation_only=False, approved_dataset_ids=(), approved_dataset_field_ids=None, approved_semantic_vocabulary=None):
    if grounding_mode == 'freeform_llm' and approved_semantic_vocabulary is None and (not annotation_only):
        schema_name = {'domain': 'metadata-freeform-domain-ir.schema.json', 'dataset': 'metadata-freeform-dataset-ir.schema.json', 'main_filter': 'metadata-freeform-main-filter-ir.schema.json'}.get(kind)
        draft_schema = load_schema(schema_name) if schema_name else {}
    elif kind == 'domain':
        draft_schema = load_schema('metadata-annotation-proposal.schema.json' if annotation_only else 'metadata-authoring-draft.schema.json')
    elif kind == 'dataset':
        draft_schema = load_schema('metadata-bootstrap-dataset-ir.schema.json')
    elif kind == 'main_filter':
        draft_schema = load_schema('metadata-bootstrap-main-filter-ir.schema.json')
        if approved_semantic_vocabulary is not None:
            draft_schema = _apply_main_filter_ir_allowlists(draft_schema, approved_semantic_vocabulary)
    else:
        return {}
    approved_ids = sorted({str(item).strip() for item in approved_dataset_ids or () if str(item).strip()})
    if kind == 'dataset' and approved_ids:
        field_allowlists = {dataset_id: sorted({str(field_id).strip() for field_id in (approved_dataset_field_ids or {}).get(dataset_id) or [] if str(field_id).strip()}) for dataset_id in approved_ids}
        if any((not field_ids for field_ids in field_allowlists.values())):
            raise ContractError('metadata_dependency_error', 'metadata_source_context', '승인 dataset별 field allowlist가 비어 있습니다.')
        base_dataset_card = deepcopy(draft_schema['$defs']['datasetCard'])
        base_field_card = deepcopy(draft_schema['$defs']['fieldCard'])
        branches = []
        for dataset_id in approved_ids:
            card = deepcopy(base_dataset_card)
            card['properties']['dataset_id'] = {'type': 'string', 'enum': [dataset_id]}
            field_card = deepcopy(base_field_card)
            field_card['properties']['id'] = {'type': 'string', 'enum': field_allowlists[dataset_id]}
            field_card['properties']['col'] = {'type': 'string', 'enum': field_allowlists[dataset_id]}
            card['properties']['fields']['items'] = field_card
            branches.append(card)
        draft_schema['$defs']['datasetCard'] = {'oneOf': branches}
    if grounding_mode != 'freeform_llm' or annotation_only:
        return draft_schema
    proposal_schema = deepcopy(load_schema('metadata-authoring-proposal.schema.json'))
    draft_definitions = {}
    proposal_definitions = proposal_schema.setdefault('$defs', {})
    if set(draft_definitions) & set(proposal_definitions):
        raise ContractError('metadata_schema_error', 'metadata_prompt_contract', '등록 초안 schema definition 이름이 proposal 계약과 충돌합니다.')
    proposal_definitions.update(draft_definitions)
    for branch in proposal_schema.get('oneOf') or []:
        properties = branch.get('properties') if isinstance(branch, dict) else None
        required = branch.get('required') if isinstance(branch, dict) else None
        if not isinstance(properties, dict) or not isinstance(required, list):
            continue
        properties['source_sha256'] = {'type': 'string', 'const': source_sha256}
        if 'source_sha256' not in required:
            required.append('source_sha256')
        if (properties.get('status') or {}).get('const') == 'complete':
            properties['draft'] = deepcopy(draft_schema)
    return proposal_schema

def _bootstrap_schema_material(value):
    if isinstance(value, list):
        return [_bootstrap_schema_material(child) for child in value]
    if isinstance(value, dict):
        return {key: _bootstrap_schema_material(child) for key, child in value.items() if key != 'description'}
    return deepcopy(value)

def _compact_detail_field_ids(raw_values, raw_fields, dataset_id):
    """Resolve compact detail entries to canonical field IDs, fail closed."""
    lookup = {}
    for raw_field in raw_fields:
        field_id = str(raw_field['id'])
        names = [field_id, raw_field.get('col')]
        names.extend(raw_field.get('physical_aliases') or [])
        names.extend(raw_field.get('aliases') or [])
        for name in names:
            key = re.sub('\\s+', ' ', str(name or '').strip()).casefold()
            if key:
                lookup.setdefault(key, set()).add(field_id)
    resolved = []
    seen = set()
    for detail_index, raw_value in enumerate(raw_values or []):
        key = re.sub('\\s+', ' ', str(raw_value or '').strip()).casefold()
        candidates = sorted(lookup.get(key) or [])
        if len(candidates) != 1:
            raise ContractError('metadata_schema_error', 'metadata_authoring', '기본 상세 필드를 데이터셋 내부 canonical field 하나로 확정할 수 없습니다.', {'dataset_id': dataset_id, 'detail_index': detail_index, 'candidate_count': len(candidates), 'detail_value_sha256': hashlib.sha256(str(raw_value or '').encode('utf-8')).hexdigest()})
        field_id = candidates[0]
        if field_id in seen:
            raise ContractError('metadata_schema_error', 'metadata_authoring', '기본 상세 필드가 canonical field 기준으로 중복되었습니다.', {'dataset_id': dataset_id, 'detail_index': detail_index, 'field_id': field_id})
        seen.add(field_id)
        resolved.append(field_id)
    return resolved

def _normalized_descriptor_name(value):
    return re.sub('\\s+', ' ', str(value or '').strip()).casefold()

def _validated_dataset_descriptor(dataset_id, raw_descriptor):
    """Validate the engine-side source descriptor without trusting the UI node."""
    id_pattern = re.compile('^[A-Za-z][A-Za-z0-9_.-]{0,127}$')
    semantic_type_pattern = re.compile('^[A-Za-z][A-Za-z0-9_]{0,63}$')
    allowed_descriptor_keys = {'physical_column', 'semantic_type', 'roles', 'physical_aliases', 'coercion', 'nullable', 'required_in_source', 'timezone'}
    if not isinstance(raw_descriptor, dict) or set(raw_descriptor) != {'family', 'fields', 'proposal_exclusions', 'dataset_template', 'dataset_template_sha256'}:
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 dataset descriptor 계약이 닫혀 있지 않습니다.', {'dataset_id': str(dataset_id)})
    family = str(raw_descriptor.get('family') or '').strip()
    raw_fields = raw_descriptor.get('fields')
    raw_exclusions = raw_descriptor.get('proposal_exclusions')
    if not id_pattern.fullmatch(family) or not isinstance(raw_fields, dict) or (not raw_fields) or (not isinstance(raw_exclusions, dict)) or (len(raw_exclusions) > 2048):
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 dataset family 또는 field descriptor가 유효하지 않습니다.', {'dataset_id': str(dataset_id)})
    fields = {}
    for field_id in sorted(raw_fields):
        raw_field = raw_fields.get(field_id)
        if not id_pattern.fullmatch(str(field_id)) or not isinstance(raw_field, dict) or (not {'physical_column', 'semantic_type', 'roles'} <= set(raw_field) <= allowed_descriptor_keys):
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 field descriptor의 ID 또는 key 계약이 유효하지 않습니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id)})
        physical_column = str(raw_field.get('physical_column') or '').strip()
        semantic_type = str(raw_field.get('semantic_type') or '').strip()
        roles = raw_field.get('roles')
        physical_aliases = raw_field.get('physical_aliases') or []
        if not physical_column or len(physical_column) > 256 or (not semantic_type_pattern.fullmatch(semantic_type)) or (not isinstance(roles, list)) or (not roles) or (len(roles) != len(set(roles))) or (not set(roles) <= set(AUTHORING_FIELD_ROLE_ORDER)) or (not isinstance(physical_aliases, list)) or (len(physical_aliases) != len(set(physical_aliases))) or any((not isinstance(value, str) or not value.strip() for value in physical_aliases)):
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 field descriptor의 물리 컬럼, 타입 또는 역할이 유효하지 않습니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id)})
        normalized = deepcopy(raw_field)
        normalized['physical_column'] = physical_column
        normalized['semantic_type'] = semantic_type
        normalized['roles'] = [role for role in AUTHORING_FIELD_ROLE_ORDER if role in roles]
        if physical_aliases:
            normalized['physical_aliases'] = list(physical_aliases)
        fields[str(field_id)] = normalized
    try:
        dataset_template = _validated_dataset_template(dataset_id, raw_descriptor.get('dataset_template'), raw_descriptor.get('dataset_template_sha256'), fields)
    except ValueError as exc:
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 dataset template 또는 hash가 유효하지 않습니다.', {'dataset_id': str(dataset_id)}) from exc
    approved_names = {_normalized_descriptor_name(name) for field_id, descriptor in fields.items() for name in (field_id, descriptor.get('physical_column'), *(descriptor.get('physical_aliases') or [])) if _normalized_descriptor_name(name)}
    exclusion_reasons = {'source_projection_not_registered', 'source_expression_before_alias', 'legacy_source_name'}
    proposal_exclusions = {}
    folded_exclusions = set()
    for raw_name in sorted(raw_exclusions):
        folded = _normalized_descriptor_name(raw_name)
        policy = raw_exclusions.get(raw_name)
        if not isinstance(policy, dict):
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 proposal exclusion policy는 object여야 합니다.', {'dataset_id': str(dataset_id)})
        reason = policy.get('reason_code')
        expected_policy_keys = {'reason_code', 'target_field_id'} if reason in {'source_expression_before_alias', 'legacy_source_name'} else {'reason_code'}
        if not isinstance(raw_name, str) or not raw_name.strip() or len(raw_name) > 256 or any((ord(character) < 32 for character in raw_name)) or (reason not in exclusion_reasons) or (set(policy) != expected_policy_keys) or (folded in folded_exclusions) or (folded in approved_names):
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 proposal exclusion 이름 또는 사유가 유효하지 않습니다.', {'dataset_id': str(dataset_id)})
        target_field_id = policy.get('target_field_id')
        if target_field_id is not None and target_field_id not in fields:
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '승인 proposal exclusion target field가 존재하지 않습니다.', {'dataset_id': str(dataset_id)})
        folded_exclusions.add(folded)
        proposal_exclusions[raw_name] = {key: policy[key] for key in sorted(policy)}
    return {'family': family, 'fields': fields, 'proposal_exclusions': proposal_exclusions, 'dataset_template': dataset_template, 'dataset_template_sha256': str(raw_descriptor.get('dataset_template_sha256') or '')}

def _descriptor_field_lookup(descriptor_fields):
    lookup = {}
    for field_id, descriptor in descriptor_fields.items():
        names = [field_id, descriptor.get('physical_column')]
        names.extend(descriptor.get('physical_aliases') or [])
        for name in names:
            key = _normalized_descriptor_name(name)
            if key:
                lookup.setdefault(key, set()).add(str(field_id))
    return lookup

def _resolve_compact_field_card(raw_field, dataset_descriptor, dataset_id, field_index):
    descriptor_fields = dataset_descriptor['fields']
    exclusion_lookup = {_normalized_descriptor_name(name): policy for name, policy in dataset_descriptor['proposal_exclusions'].items()}
    lookup = _descriptor_field_lookup(descriptor_fields)
    id_name = _normalized_descriptor_name(raw_field.get('id'))
    col_name = _normalized_descriptor_name(raw_field.get('col'))
    id_candidates = set(lookup.get(id_name) or [])
    col_candidates = set(lookup.get(col_name) or [])

    def fail_resolution(code, stage, message, candidate_count):
        raise ContractError(code, stage, message, {'dataset_id': str(dataset_id), 'field_index': field_index, 'candidate_count': candidate_count, 'field_id_sha256': hashlib.sha256(str(raw_field.get('id') or '').encode('utf-8')).hexdigest(), 'physical_column_sha256': hashlib.sha256(str(raw_field.get('col') or '').encode('utf-8')).hexdigest(), 'operator_action': 'review_source_registry_descriptor_or_exclusion'})
    if len(col_candidates) > 1 or len(id_candidates) > 1:
        fail_resolution('metadata_dependency_error', 'metadata_source_descriptors', 'LLM field card를 동일 dataset의 승인 descriptor 하나로 확정할 수 없습니다.', max(len(col_candidates), len(id_candidates)))
    applied_exclusion = None
    binding_corrected = False
    if col_candidates:
        field_id = sorted(col_candidates)[0]
        if id_candidates and field_id not in id_candidates:
            fail_resolution('metadata_dependency_error', 'metadata_source_descriptors', 'LLM field id와 물리 col이 서로 다른 승인 descriptor를 가리킵니다.', 0)
        binding_corrected = not id_candidates
    else:
        col_policy = exclusion_lookup.get(col_name)
        if col_policy is None:
            fail_resolution('metadata_registry_drift', 'metadata_source_registry', 'LLM이 제안한 물리 col이 승인 descriptor나 명시적 exclusion에 없습니다. 작업자가 아니라 운영자가 Source Registry를 검토해야 합니다.', 0)
        reason_code = str(col_policy.get('reason_code') or '')
        target_field_id = col_policy.get('target_field_id')
        applied_exclusion = {'name_sha256': hashlib.sha256(str(raw_field.get('col') or '').encode('utf-8')).hexdigest(), 'reason_code': reason_code, 'target_field_id': str(target_field_id or '')}
        if target_field_id is None:
            if id_candidates:
                fail_resolution('metadata_dependency_error', 'metadata_source_descriptors', '노출 제외된 물리 col을 승인 field id에 결합할 수 없습니다.', 0)
            return (None, False, applied_exclusion)
        field_id = str(target_field_id)
        if id_candidates and field_id not in id_candidates:
            fail_resolution('metadata_dependency_error', 'metadata_source_descriptors', '원천 alias exclusion target과 LLM field id가 충돌합니다.', 0)
        binding_corrected = True
    descriptor = descriptor_fields[field_id]
    proposed_roles = set(raw_field.get('roles') or [])
    approved_roles = set(descriptor.get('roles') or [])
    if not proposed_roles <= approved_roles:
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', 'LLM field role이 승인 descriptor 역할 범위를 벗어났습니다.', {'dataset_id': str(dataset_id), 'field_id': field_id})
    proposed_aliases = set(raw_field.get('physical_aliases') or [])
    approved_names = {str(field_id), str(descriptor.get('physical_column') or ''), *[str(value) for value in descriptor.get('physical_aliases') or []]}
    if proposed_aliases and (not proposed_aliases <= approved_names):
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', 'LLM physical alias가 승인 descriptor 범위를 벗어났습니다.', {'dataset_id': str(dataset_id), 'field_id': field_id})
    for key in ('coercion', 'timezone'):
        if key in raw_field and raw_field.get(key) != descriptor.get(key):
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', 'LLM 기술 field 속성이 승인 descriptor와 충돌합니다.', {'dataset_id': str(dataset_id), 'field_id': field_id, 'attribute': key})
    if raw_field.get('required_in_source') is True and descriptor.get('required_in_source') is not True:
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', 'LLM required_in_source가 승인 descriptor와 충돌합니다.', {'dataset_id': str(dataset_id), 'field_id': field_id})
    if raw_field.get('nullable') is False and descriptor.get('nullable') is not False:
        raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', 'LLM nullable이 승인 descriptor와 충돌합니다.', {'dataset_id': str(dataset_id), 'field_id': field_id})
    return (field_id, binding_corrected, applied_exclusion)

def _merge_equivalent_compact_field_cards(existing, incoming, dataset_id, field_id):
    """Merge duplicate provider cards only after one approved descriptor wins."""
    merged = deepcopy(existing)
    additive_list_keys = {'aliases'}
    bounded_list_keys = {'allowed_filter_operators', 'allowed_rollups'}
    scalar_keys = {'unit', 'null_policy', 'case_policy', 'multiplier'}
    for key in sorted(additive_list_keys):
        left = merged.get(key) or []
        right = incoming.get(key) or []
        if not isinstance(left, list) or not isinstance(right, list):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '동일 승인 field의 선택 목록 속성을 병합할 수 없습니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id), 'attribute': key})
        if left or right:
            merged[key] = sorted({str(value) for value in [*left, *right] if str(value)})
    for key in sorted(bounded_list_keys):
        if key not in incoming:
            continue
        right = incoming.get(key)
        if not isinstance(right, list):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '동일 승인 field의 허용 목록 속성을 병합할 수 없습니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id), 'attribute': key})
        if key in merged:
            left = merged.get(key)
            if not isinstance(left, list) or set(left) != set(right):
                raise ContractError('metadata_schema_error', 'metadata_authoring', '동일 승인 field의 허용 목록이 서로 충돌합니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id), 'attribute': key})
        merged[key] = sorted({str(value) for value in right if str(value)})
    for key in sorted(scalar_keys):
        if key not in incoming:
            continue
        if key in merged and merged.get(key) != incoming.get(key):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '동일 승인 field의 선택 속성이 서로 충돌합니다.', {'dataset_id': str(dataset_id), 'field_id': str(field_id), 'attribute': key})
        merged[key] = deepcopy(incoming[key])
    return merged

_FREEFORM_FIELD_ROLES = {'filter', 'group', 'join', 'compare', 'aggregate', 'derive', 'project', 'sort', 'rank', 'metric', 'output'}

def _freeform_csv_values(value):
    return [item.strip(" \t\r\n.。'") for item in re.split('\\s*,\\s*', str(value or '')) if item.strip(" \t\r\n.。'")]

def _freeform_filter_mappings(source_text):
    """Read canonical -> physical mappings directly from worker text."""
    text = str(source_text or '').replace('\r\n', '\n').replace('\r', '\n')
    marker = re.search('(?i)(?<![A-Za-z0-9_])filter_mappings(?![A-Za-z0-9_])', text)
    if marker is None:
        return {}
    tail = text[marker.end():]
    end = re.search('(?im)^\\s*(?:standard_column_aliases|default_detail_columns|metric_semantics|selection_criteria|required_params|required_param_mappings|query_template)\\s*(?:[:=]|(?:은|는)\\b)', tail)
    if end:
        tail = tail[:end.start()]
    mappings = {}
    for match in re.finditer('(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*[-=]>\\s*([A-Za-z][A-Za-z0-9_$#.-]{0,255})', tail):
        canonical, physical = (match.group(1), match.group(2))
        if canonical in mappings and mappings[canonical] != physical:
            raise ContractError('metadata_schema_error', 'metadata_dataset_mapping', 'filter_mappings에 같은 표준 필드의 물리 컬럼이 두 개 이상 지정되었습니다.', {'field_id': canonical})
        mappings[canonical] = physical
    return mappings

def _freeform_query_columns(source_text):
    """Extract simple SELECT output names without changing the SQL text."""
    text = str(source_text or '').replace('\r\n', '\n').replace('\r', '\n')
    marker = _QUERY_MARKER.search(text)
    if marker is None:
        return []
    boundary = _QUERY_BLOCK_END.search(text, marker.end())
    query = text[marker.end():boundary.start() if boundary else len(text)]
    neutral = re.sub('/\\*.*?\\*/', ' ', query, flags=re.DOTALL)
    neutral = re.sub('(?m)--[^\\n]*$', ' ', neutral)
    select_match = re.search('(?is)\\bSELECT\\b(.*?)\\bFROM\\b', neutral)
    if select_match is None:
        return []
    columns = []
    for expression in select_match.group(1).split(','):
        value = expression.strip()
        if not value:
            continue
        alias = re.search('(?i)\\bAS\\s+([A-Za-z][A-Za-z0-9_$#.-]{0,255})\\s*$', value)
        if alias:
            name = alias.group(1)
        else:
            token = value.split()[-1]
            name = token.rsplit('.', 1)[-1].strip('"')
        if re.fullmatch('[A-Za-z][A-Za-z0-9_$#.-]{0,255}', name) and name not in columns:
            columns.append(name)
    return columns

def _freeform_selection_criteria(source_text):
    text = str(source_text or '').replace('\r\n', '\n').replace('\r', '\n')
    result = {}
    scope = re.search('(?i)selection_criteria(?:의|\\.)?\\s*time_scope\\s*(?:은|는|:|=)\\s*([A-Za-z][A-Za-z0-9_.-]{0,63})', text)
    if scope:
        result['time_scope'] = scope.group(1)
    elif '당일용' in text:
        result['time_scope'] = 'current_day'
    elif '이력' in text:
        result['time_scope'] = 'history'
    use_when = re.search('(?is)selection_criteria(?:의|\\.)?\\s*use_when\\s*(?:은|는|:|=)\\s*(.*?)\\s*(?:이고|이며|,?\\s*exclude_when\\s*(?:은|는|:|=))', text)
    exclude_when = re.search('(?is)exclude_when\\s*(?:은|는|:|=)\\s*(.*?)(?:이야|입니다|해\\.?|\\n\\s*조회|\\n\\s*filter_mappings|$)', text)
    if use_when:
        result['use_when'] = _freeform_csv_values(use_when.group(1))
    if exclude_when:
        result['exclude_when'] = _freeform_csv_values(exclude_when.group(1))
    return result

def _freeform_dataset_family(source_text, dataset_id):
    text = str(source_text or '')
    patterns = (f'(?i)(?<![A-Za-z0-9_]){re.escape(dataset_id)}(?![A-Za-z0-9_]).{{0,80}}?([A-Za-z][A-Za-z0-9_.-]{{0,127}})\\s*계열', '(?i)(?:dataset_)?family\\s*(?:은|는|:|=)\\s*([A-Za-z][A-Za-z0-9_.-]{0,127})')
    for pattern in patterns:
        match = re.search(pattern, text, flags=re.DOTALL)
        if match:
            return match.group(1)
    return ''

def _freeform_source_type(source_text):
    folded = str(source_text or '').casefold()
    markers = (('oracle', 'oracle'), ('datalake', 'datalake'), ('goodocs', 'goodocs'), ('mongodb', 'mongodb'), ('h-api', 'http'), ('http', 'http'))
    for marker, source_type in markers:
        if marker in folded:
            return source_type
    return ''

def _freeform_field_semantic_type(field_id, physical_column, source_text, proposed=''):
    """Derive a stable field type without trusting the model's guess.

    The same canonical field must have one semantic type across datasets.  An
    LLM-proposed type is therefore evidence only; allowing it to win here made
    one provider response mark every production_today column as ``date``.
    Worker text and conservative identifier rules are the authority.
    """
    marker = f'{field_id} {physical_column}'.upper()
    identifier_tokens = set(re.findall('[A-Z0-9]+', marker))
    text = str(source_text or '')
    if identifier_tokens & {'DATE', 'DT', 'DATETIME', 'TIMESTAMP', 'TIME', 'AT'}:
        return 'date'
    if identifier_tokens & {'QTY', 'QUANTITY', 'COUNT', 'CNT', 'AMOUNT', 'PRODUCTION', 'WIP', 'PRESS', 'SEQ', 'TAT', 'UPH', 'RATE', 'YIELD'}:
        return 'number'
    identifiers = [str(field_id or '').strip(), str(physical_column or '').strip()]
    for sentence in re.split('[\\r\\n.!?]+', text):
        if not any((identifier and re.search(f'(?<![A-Za-z0-9_]){re.escape(identifier)}(?![A-Za-z0-9_])', sentence, re.IGNORECASE) for identifier in identifiers)):
            continue
        if re.search('YYYY[- ]?MM[- ]?DD|날짜|기준일|일자|시각|시간', sentence, re.IGNORECASE):
            return 'date'
        if re.search('수량|생산량|건수|합계|개수|대수|평균|비율', sentence):
            return 'number'
    return 'string'

def _freeform_field_roles(field_id, physical_column, explicit_mappings, semantic_type, proposed=None):
    if field_id in explicit_mappings:
        return ['filter', 'group', 'project', 'output']
    if semantic_type in {'number', 'integer', 'decimal', 'float'} and re.search('(?:QTY|QUANTITY|COUNT|CNT|AMOUNT|PRODUCTION|WIP|UPH|TAT|RATE|YIELD)', f'{field_id} {physical_column}', re.IGNORECASE):
        return ['aggregate', 'metric', 'output']
    return ['project', 'output']

def _freeform_field_declared_aliases(field_id, physical_column, source_text):
    """Extract explicit worker labels without asking the model to infer them."""
    names = {str(field_id or '').strip().casefold(), str(physical_column or '').strip().casefold()}
    names.discard('')
    aliases = []
    for name in sorted(names, key=len, reverse=True):
        pattern = re.compile(f'(?<![A-Za-z0-9_.-]){re.escape(name)}(?![A-Za-z0-9_.-])\\s*컬럼.{{0,120}}?(?:이\\s*값|해당\\s*값|그\\s*값)\\s*(?:은|는)\\s*(?P<label>[가-힣A-Za-z][가-힣A-Za-z0-9 _./-]{{0,39}}?)(?=\\s*(?:이야|야|입니다|이다|을\\s*의미|를\\s*의미))', re.IGNORECASE | re.DOTALL)
        for match in pattern.finditer(str(source_text or '')):
            label = ' '.join(str(match.group('label') or '').strip().split())
            if label and label not in aliases:
                aliases.append(label)
    return aliases

def _freeform_dataset_source_segment(source_text, dataset_id):
    """Return only the worker-authored block that registers ``dataset_id``.

    A worker may keep several item-sized registrations in one TXT file for
    convenience, while the authoring Flow still processes one dataset card at
    a time.  Field mappings and SQL columns must never bleed from a neighboring
    dataset block.  The explicit ``<id>로/으로 등록`` sentences are the stable
    natural-language boundaries used by the v5 inputs as well as v6.
    """
    text = str(source_text or '')
    marker = re.compile('(?im)^[^\\r\\n]*?(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*(?:으)?로\\s*등록[^\\r\\n]*$')
    matches = list(marker.finditer(text))
    for index, match in enumerate(matches):
        if match.group(1) != str(dataset_id or ''):
            continue
        end = matches[index + 1].start() if index + 1 < len(matches) else len(text)
        return text[match.start():end]
    return text

def _expand_freeform_dataset_fragment(fragment, source_text, reconciliation_out=None):
    """Expand v5-style dataset cards using only explicit worker text."""
    if not isinstance(fragment, dict) or set(fragment) != {'dataset_cards'}:
        raise ContractError('metadata_schema_error', 'metadata_authoring', '테이블 카탈로그 등록 결과는 dataset_cards 목록이어야 합니다.')
    cards = fragment.get('dataset_cards')
    if not isinstance(cards, list) or not cards:
        raise ContractError('metadata_schema_error', 'metadata_authoring', '등록할 데이터셋 항목이 없습니다.')
    explicit_dataset_id = _freeform_dataset_id(source_text)
    datasets = {}
    dataset_identity_overrides = []
    discarded_model_semantic_types = 0
    total_filter_mappings = 0
    total_query_columns = 0
    selection_criteria_from_text = False
    for card_index, raw_card in enumerate(cards):
        if not isinstance(raw_card, dict):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '데이터셋 card는 object여야 합니다.')
        proposed_dataset_id = str(raw_card.get('dataset_id') or '').strip()
        dataset_id = explicit_dataset_id if len(cards) == 1 and explicit_dataset_id else proposed_dataset_id
        if proposed_dataset_id and proposed_dataset_id != dataset_id:
            dataset_identity_overrides.append({'proposed': proposed_dataset_id, 'source_authority': dataset_id})
        if not re.fullmatch('[A-Za-z][A-Za-z0-9_.-]{0,127}', dataset_id) or dataset_id in datasets:
            raise ContractError('metadata_schema_error', 'metadata_authoring', 'dataset_id가 없거나 중복되었습니다.', {'dataset_index': card_index, 'dataset_id': dataset_id})
        dataset_source_text = _freeform_dataset_source_segment(source_text, dataset_id)
        explicit_mappings = _freeform_filter_mappings(dataset_source_text)
        query_columns = _freeform_query_columns(dataset_source_text)
        query_column_set = {value.casefold() for value in query_columns}
        selection_from_text = _freeform_selection_criteria(dataset_source_text)
        reverse_mapping = {physical.casefold(): canonical for canonical, physical in explicit_mappings.items()}
        total_filter_mappings += len(explicit_mappings)
        total_query_columns += len(query_columns)
        selection_criteria_from_text = selection_criteria_from_text or bool(selection_from_text)
        family = str(_freeform_dataset_family(dataset_source_text, dataset_id) or dataset_id).strip()
        source_type = str(_freeform_source_type(dataset_source_text) or raw_card.get('source_type') or '').strip().casefold()
        if not family or source_type not in {'oracle', 'sql', 'mongodb', 'http', 'datalake', 'goodocs', 'file', 'dummy', 'previous_result'}:
            raise ContractError('metadata_clarification_required', 'metadata_clarification', '데이터 계열 또는 원천 종류를 자연어 설명에서 확인할 수 없습니다.', {'questions': ['데이터셋의 계열 이름과 원천 종류를 알려주세요.'], 'missing_fields': ['데이터 계열 또는 원천 종류']})
        model_fields = {}
        for field_index, raw_field in enumerate(raw_card.get('fields') or []):
            if not isinstance(raw_field, dict):
                raise ContractError('metadata_schema_error', 'metadata_authoring', 'field card는 object여야 합니다.')
            field_id = str(raw_field.get('id') or '').strip()
            physical = str(raw_field.get('col') or '').strip()
            if not re.fullmatch('[A-Za-z][A-Za-z0-9_.-]{0,127}', field_id) or not physical:
                raise ContractError('metadata_schema_error', 'metadata_authoring', 'field card의 id 또는 col이 올바르지 않습니다.', {'dataset_id': dataset_id, 'field_index': field_index})
