                discarded_model_semantic_types += 1
            binding = {'physical_column': physical, 'semantic_type': semantic_type, 'roles': _freeform_field_roles(field_id, physical, explicit_mappings, semantic_type, raw_field.get('roles'))}
            aliases = [str(item).strip() for item in raw_field.get('aliases') or [] if str(item).strip()]
            for alias in _freeform_field_declared_aliases(field_id, physical, dataset_source_text):
                if alias not in aliases:
                    aliases.append(alias)
            if aliases:
                binding['aliases'] = list(dict.fromkeys(aliases))
            if str(raw_field.get('unit') or '').strip():
                binding['unit'] = str(raw_field['unit']).strip()
            model_fields[field_id] = binding
        for canonical, physical in explicit_mappings.items():
            if canonical not in model_fields:
                semantic_type = _freeform_field_semantic_type(canonical, physical, dataset_source_text)
                model_fields[canonical] = {'physical_column': physical, 'semantic_type': semantic_type, 'roles': _freeform_field_roles(canonical, physical, explicit_mappings, semantic_type)}
                aliases = _freeform_field_declared_aliases(canonical, physical, dataset_source_text)
                if aliases:
                    model_fields[canonical]['aliases'] = aliases
        for physical in query_columns:
            canonical = reverse_mapping.get(physical.casefold(), physical)
            if canonical not in model_fields:
                semantic_type = _freeform_field_semantic_type(canonical, physical, dataset_source_text)
                model_fields[canonical] = {'physical_column': physical, 'semantic_type': semantic_type, 'roles': _freeform_field_roles(canonical, physical, explicit_mappings, semantic_type)}
                aliases = _freeform_field_declared_aliases(canonical, physical, dataset_source_text)
                if aliases:
                    model_fields[canonical]['aliases'] = aliases
        if not model_fields:
            raise ContractError('metadata_clarification_required', 'metadata_clarification', '조회 결과 컬럼 또는 필터 매핑을 확인할 수 없습니다.', {'questions': ['조회 결과 컬럼이나 필터 매핑을 자연어로 알려주세요.'], 'missing_fields': ['조회 컬럼']})
        selection = deepcopy(raw_card.get('selection_criteria') or {})
        for key, value in selection_from_text.items():
            selection[key] = deepcopy(value)
        time_scope = str(selection.get('time_scope') or raw_card.get('time_scope') or 'unspecified')
        if time_scope:
            selection['time_scope'] = time_scope
        parameters = deepcopy(dict(raw_card.get('parameters') or {}))
        placeholders = list(dict.fromkeys((match.group(1).strip() for match in re.finditer('\\{([A-Za-z][A-Za-z0-9_]*)\\}', dataset_source_text))))
        date_policy = deepcopy(raw_card.get('date_policy')) if isinstance(raw_card.get('date_policy'), dict) else None
        for name in placeholders:
            spec = deepcopy(dict(parameters.get(name) or {}))
            binding = model_fields.get(name) if isinstance(model_fields.get(name), dict) else {}
            if str(binding.get('semantic_type') or '').casefold() in {'localdate', 'date'}:
                spec['type'] = 'LocalDate'
                compact_pattern = re.compile(f'(?<![A-Za-z0-9_]){re.escape(name)}(?![A-Za-z0-9_]).{{0,80}}?YYYYMMDD\\s*형식', re.IGNORECASE | re.DOTALL)
