                if compact_pattern.search(dataset_source_text):
                    spec['format'] = 'YYYYMMDD'
                elif dashed_pattern.search(dataset_source_text):
                    spec['format'] = 'YYYY-MM-DD'
                if date_policy is None:
                    date_policy = {'field': name, 'inclusive_start': True, 'inclusive_end': True, 'timezone': 'Asia/Seoul'}
            else:
                spec.setdefault('type', 'string')
            spec['required'] = True
            parameters[name] = spec
        dataset = {'display_name': str(raw_card.get('display_name') or dataset_id), 'family': family, 'source_type': source_type, 'time_scope': time_scope, 'selection_criteria': selection, 'fields': {key: model_fields[key] for key in sorted(model_fields)}}
        if parameters:
            dataset['parameters'] = parameters
        if date_policy is not None:
            dataset['date_policy'] = date_policy
        if raw_card.get('default_detail_fields'):
            dataset['default_detail_fields'] = list(raw_card['default_detail_fields'])
        datasets[dataset_id] = dataset
    evidence = {'contract_version': 'metadata.freeform-dataset-expansion.v1', 'dataset_count': len(datasets), 'field_count': sum((len(item['fields']) for item in datasets.values())), 'filter_mapping_count': total_filter_mappings, 'query_column_count': total_query_columns, 'selection_criteria_from_text': selection_criteria_from_text, 'dataset_identity_overrides': dataset_identity_overrides, 'discarded_model_semantic_type_count': discarded_model_semantic_types}
    if isinstance(reconciliation_out, dict):
        reconciliation_out.clear()
        reconciliation_out.update(evidence)
    return {'datasets': {key: datasets[key] for key in sorted(datasets)}}

def _freeform_recipe_identity(key, payload, source_text=''):
    """Resolve the recipe id from explicit model data or the operator's text.

    Smaller models sometimes replace dots with underscores in the compact
    item key.  The operator-authored identifier remains authoritative when it
    is explicitly written next to the word ``recipe``.
    """
    explicit = str((payload or {}).get('recipe_id') or '').strip()
    if not explicit and source_text:
        matches = re.findall('(?:recipe|레시피)\\s*(?:를|을)?\\s*(?:as\\s+)?([A-Za-z0-9_.-]+)\\s*(?:로|으로)?', str(source_text), flags=re.IGNORECASE)
        matches = [value.rstrip('.') for value in matches if value.rstrip('.')]
        if len(set(matches)) == 1:
            explicit = matches[0]
    return explicit or str(key or '').strip()

def _freeform_recipe_keys(payload, source_text=''):
    grain_payload = (payload or {}).get('grain')
    candidates = []
    if isinstance(grain_payload, dict):
        candidates = grain_payload.get('keys') or []
    if not candidates:
        candidates = (payload or {}).get('keys') or (payload or {}).get('grain_keys') or (payload or {}).get('product_keys') or []
    if not candidates and source_text:
        match = re.search('(?:grain\\s*)?(?:keys?|key|키)(?:\\s*목록)?\\s*(?:은|는|:|=|is)\\s*([^\\r\\n.]+)', str(source_text), flags=re.IGNORECASE)
        if match:
            candidates = re.split('\\s*(?:,|→|->|/|그리고)\\s*', match.group(1))
    return list(dict.fromkeys((str(value).strip().rstrip('이야입니다') for value in candidates if re.fullmatch('[A-Za-z][A-Za-z0-9_]*', str(value).strip().rstrip('이야입니다')))))

def _normalize_freeform_recipe(key, payload, source_text=''):
    recipe_id = _freeform_recipe_identity(key, payload, source_text)
    template = deepcopy((payload or {}).get('default_operation_template'))
    keys = _freeform_recipe_keys(payload, source_text)
    raw_grain = (payload or {}).get('grain')
    grain_ref = ''
    if isinstance(raw_grain, str):
        grain_ref = raw_grain.strip()
    elif isinstance(raw_grain, dict):
        grain_ref = str(raw_grain.get('entity_id') or raw_grain.get('grain_ref') or raw_grain.get('grain_id') or '').strip()
    if not grain_ref and source_text:
        match = re.search('grain\\s*(?:은|는|:|=|is)\\s*([A-Za-z][A-Za-z0-9_.-]*)', str(source_text), flags=re.IGNORECASE)
        if match:
            grain_ref = match.group(1)
    if not isinstance(template, dict) and keys:
        template = {'op': 'aggregate', 'group_by': keys, 'metrics': [{'as_ref': '$metric.id', 'field_ref': '$metric.field', 'function_ref': '$metric.rollup'}]}
    slot_aliases = {'dataset': 'dataset_refs', 'metric': 'metric_refs', 'grain': 'grain_refs', 'field': 'field_refs', 'relation': 'relation_refs', 'recipe': 'recipe_refs', 'entity_group': 'entity_group_refs', 'filter': 'filter_refs'}

    def _clean_alias(value):
        text = str(value or '').strip()
        return re.sub('(?:이야|예요|입니다|야)$', '', text).strip()
    recipe = {'recipe_id': recipe_id, 'aliases': list(dict.fromkeys((_clean_alias(value) for value in (payload or {}).get('aliases') or [] if _clean_alias(value)))), 'required_slots': list(dict.fromkeys((slot_aliases.get(str(value).strip(), str(value).strip()) for value in (payload or {}).get('required_slots') or ['dataset', 'metric'] if str(value).strip())))}
    if isinstance(template, dict):
        recipe['default_operation_template'] = template
    if keys:
        recipe['grain'] = {'entity_id': grain_ref or recipe_id.split('.', 1)[0], 'grain_id': recipe_id, 'keys': keys, 'null_match_policy': str((raw_grain or {}).get('null_match_policy') if isinstance(raw_grain, dict) else 'blank_equals_blank') or 'blank_equals_blank'}
    for name in ('display_name', 'description'):
        if (payload or {}).get(name):
            recipe[name] = str(payload[name])
    return (recipe_id, recipe)

def _expand_freeform_domain_fragment(fragment, reconciliation_out=None, source_text=''):
    if not isinstance(fragment, dict) or set(fragment) != {'items'}:
        raise ContractError('metadata_schema_error', 'metadata_authoring', '도메인 등록 결과는 items 목록이어야 합니다.')
    patch = {}
    seen = set()
    raw_items = fragment.get('items') or []
    has_business_item = any((isinstance(item, dict) and str(item.get('section') or '') != 'profile' for item in raw_items))
    discarded_profile_items = 0
    for index, item in enumerate(raw_items):
        section = str((item or {}).get('section') or '') if isinstance(item, dict) else ''
        key = str((item or {}).get('key') or '') if isinstance(item, dict) else ''
        payload = deepcopy((item or {}).get('payload') or {}) if isinstance(item, dict) else {}
        if section == 'recipes':
            key, payload = _normalize_freeform_recipe(key, payload, source_text)
        identity = (section, key)
        if identity in seen:
            raise ContractError('metadata_schema_error', 'metadata_authoring', '도메인 items에 중복 section/key가 있습니다.', {'item_index': index})
        seen.add(identity)
        if section == 'profile':
