                discarded_profile_items += 1
                continue
            if any((name in patch for name in ('display_name', 'description', 'locale', 'timezone'))):
                raise ContractError('metadata_schema_error', 'metadata_authoring', '도메인 프로필은 한 항목만 등록할 수 있습니다.')
            patch['domain_id'] = key
            patch['display_name'] = str(payload.get('display_name') or key)
            for name in ('description', 'locale', 'timezone'):
                if name in payload:
                    patch[name] = deepcopy(payload[name])
            continue
        if section == 'entity_groups':
            target_field = str(payload.get('target_field') or payload.get('field') or '').strip()
            members = payload.get('members') if isinstance(payload.get('members'), list) else payload.get('processes')
            aliases = payload.get('aliases') if isinstance(payload.get('aliases'), list) else []
            group = {'group_id': key, 'display_name': str(payload.get('display_name') or key), 'target_field': target_field, 'members': [re.sub('(?:입니다|이에요|예요|이야|야)$', '', str(value).strip()).strip() for value in members or [] if str(value).strip()], 'aliases': [str(value).strip() for value in aliases if str(value).strip()]}
            if not group['target_field'] or not group['members'] or (not group['aliases']):
                raise ContractError('metadata_clarification_required', 'metadata_clarification', '공정 그룹의 적용 필드, 포함 값 또는 별칭이 부족합니다.', {'questions': ['공정 그룹의 적용 필드, 포함 값, 별칭을 알려주세요.'], 'missing_fields': ['공정 그룹 설명']})
            patch.setdefault(section, {})[key] = group
            continue
        if section == 'metrics':
            source_binding = deepcopy(payload.get('source_binding')) if isinstance(payload.get('source_binding'), dict) else {}
            dataset_family = str(source_binding.get('dataset_family') or payload.get('dataset_family') or '').strip()
            source_field = str(source_binding.get('field') or payload.get('source_field') or '').strip()
            if not dataset_family and source_text:
                match = re.search('([A-Za-z][A-Za-z0-9_.-]*)\\s*(?:계열|family)', str(source_text), flags=re.IGNORECASE)
                if match:
                    dataset_family = match.group(1)
            if not source_field and source_text:
                match = re.search('([A-Za-z][A-Za-z0-9_]*)\\s*(?:컬럼|column|field)', str(source_text), flags=re.IGNORECASE)
                if match:
                    source_field = match.group(1)
            formula = deepcopy(payload.get('formula')) if isinstance(payload.get('formula'), dict) else None
            if dataset_family and source_field:
                source_binding = {'dataset_family': dataset_family, 'field': source_field}
            allowed_rollups = payload.get('allowed_rollups')
            if not isinstance(allowed_rollups, list):
                allowed_rollups = payload.get('allowed_aggregations')
            allowed_rollups = [str(value).strip().casefold() for value in allowed_rollups or [] if str(value).strip()]
            default_rollup = str((payload.get('additivity') or {}).get('default') if isinstance(payload.get('additivity'), dict) else payload.get('default_aggregation') or payload.get('aggregation') or '').strip().casefold()
            if isinstance(payload.get('additivity'), dict):
                additivity = deepcopy(payload['additivity'])
            else:
                if not allowed_rollups and default_rollup:
                    allowed_rollups = [default_rollup]
                default_kind = 'distinct' if default_rollup in {'count_distinct', 'nunique', 'list_unique'} else 'non_additive' if default_rollup in {'mean', 'avg', 'average', 'min', 'max'} else 'additive'
                additivity = {'default': default_kind, 'allowed_rollups': list(dict.fromkeys(allowed_rollups or ['sum']))}
            metric = {'metric_id': key, 'value_type': str(payload.get('value_type') or 'number'), 'unit': str(payload.get('unit') or 'count'), 'null_policy': str(payload.get('null_policy') or ('exclude_from_sum' if payload.get('exclude_nulls') is not False else 'preserve_null')), 'zero_policy': str(payload.get('zero_policy') or 'preserve_zero'), 'additivity': additivity}
            aliases = [str(value).strip() for value in payload.get('aliases') or [] if str(value).strip()]
            if aliases:
                metric['aliases'] = list(dict.fromkeys(aliases))
            if source_binding:
                metric['source_binding'] = source_binding
            if formula is not None:
                metric['formula'] = formula
            if isinstance(payload.get('dependencies'), list):
