        if section == 'grains':
            keys = payload.get('keys')
            if not isinstance(keys, list):
                keys = payload.get('grain_keys')
            grain = {'grain_id': key, 'keys': [re.sub('(?:입니다|이에요|예요|이야|야)$', '', str(value).strip()).strip() for value in keys or [] if str(value).strip()]}
            display_fields = payload.get('display_fields')
            if isinstance(display_fields, list) and display_fields:
                grain['display_fields'] = [str(value).strip() for value in display_fields if str(value).strip()]
            patch.setdefault(section, {})[key] = grain
            continue
        if section == 'recipes':
            patch.setdefault(section, {})[key] = payload
            continue
        patch.setdefault(section, {})[key] = payload
    if not patch:
