    return patch

def _expand_freeform_main_filter_fragment(fragment):
    if not isinstance(fragment, dict) or set(fragment) != {'items'}:
        raise ContractError('metadata_schema_error', 'metadata_authoring', '메인 필터 등록 결과는 items 목록이어야 합니다.')
    additions = []
    seen = set()
    for index, item in enumerate(fragment.get('items') or []):
        filter_key = str((item or {}).get('filter_key') or '') if isinstance(item, dict) else ''
        payload = (item or {}).get('payload') if isinstance(item, dict) else None
        aliases = [str(value).strip() for value in (payload or {}).get('aliases') or [] if str(value).strip()] if isinstance(payload, dict) else []
        if not filter_key or filter_key in seen or (not aliases):
            raise ContractError('metadata_schema_error', 'metadata_authoring', '메인 필터 key가 중복되었거나 별칭이 없습니다.', {'item_index': index, 'filter_key': filter_key})
        seen.add(filter_key)
        additions.append({'target_type': 'field', 'target_id': filter_key, 'expressions': aliases})
    return {'alias_additions': additions}

def _expand_compact_dataset_fragment(fragment, dataset_descriptors=None, reconciliation_out=None):
    """Expand the LLM-facing compact Dataset IR into the full draft section.

    The LLM never receives physical/type/role descriptors.  This deterministic
    step resolves its compact field cards against the operator-approved source
    registry and fills omitted cards from that same dataset only.
    """
    dataset_descriptors = dataset_descriptors if isinstance(dataset_descriptors, dict) else {}
    datasets = {}
    completed_pairs = []
    normalized_pairs = []
    applied_exclusion_rows = []
    corrected_binding_pairs = []
    applied_dataset_templates = []
    approved_field_count = 0
    model_field_count = 0
    for dataset_index, raw_card in enumerate(fragment.get('dataset_cards') or []):
        dataset_id = str(raw_card['dataset_id'])
        if dataset_id in datasets:
            raise ContractError('metadata_schema_error', 'metadata_authoring', '압축 데이터셋 등록 IR에 중복 dataset_id가 있습니다.', {'dataset_id': dataset_id, 'dataset_index': dataset_index})
        if dataset_id not in dataset_descriptors:
            raise ContractError('metadata_dependency_error', 'metadata_source_descriptors', '동일 dataset의 승인 source descriptor가 없습니다.', {'dataset_id': dataset_id})
        descriptor = _validated_dataset_descriptor(dataset_id, dataset_descriptors[dataset_id])
        applied_dataset_templates.append({'dataset_id': dataset_id, 'dataset_template_sha256': descriptor['dataset_template_sha256']})
        descriptor_fields = descriptor['fields']
        approved_field_count += len(descriptor_fields)
        resolved_model_fields = {}
        for field_index, raw_field in enumerate(raw_card['fields']):
            field_id, binding_corrected, applied_exclusion = _resolve_compact_field_card(raw_field, descriptor, dataset_id, field_index)
            if applied_exclusion is not None:
                applied_exclusion_rows.append({'dataset_id': dataset_id, **applied_exclusion})
            if field_id is None:
                model_field_count += 1
                continue
            if binding_corrected:
                corrected_binding_pairs.append({'dataset_id': dataset_id, 'field_id': field_id, 'proposed_id_sha256': hashlib.sha256(str(raw_field.get('id') or '').encode('utf-8')).hexdigest(), 'proposed_column_sha256': hashlib.sha256(str(raw_field.get('col') or '').encode('utf-8')).hexdigest()})
            if field_id in resolved_model_fields:
                resolved_model_fields[field_id] = _merge_equivalent_compact_field_cards(resolved_model_fields[field_id], raw_field, dataset_id, field_id)
            else:
                resolved_model_fields[field_id] = raw_field
            model_field_count += 1
            normalized_pairs.append({'dataset_id': dataset_id, 'field_id': field_id})
        fields = {}
        for field_id in sorted(descriptor_fields):
            approved = descriptor_fields[field_id]
            binding = deepcopy(approved)
            raw_field = resolved_model_fields.get(field_id)
            if raw_field is None:
                completed_pairs.append({'dataset_id': dataset_id, 'field_id': field_id})
                fields[field_id] = binding
                continue
            fields[field_id] = binding
        dataset = deepcopy(descriptor['dataset_template'])
        dataset['family'] = descriptor['family']
        dataset['fields'] = {key: fields[key] for key in sorted(fields)}
        for key in COMPACT_DATASET_CARD_OPTIONAL:
            if key in raw_card:
                dataset[key] = deepcopy(raw_card[key])
        datasets[dataset_id] = dataset
    evidence = {'contract_version': 'metadata.dataset-registry-reconciliation.v1', 'approved_field_count': approved_field_count, 'model_field_count': model_field_count, 'completed_field_count': len(completed_pairs), 'applied_exclusion_count': len(applied_exclusion_rows), 'applied_exclusions_sha256': sha256_json(sorted(applied_exclusion_rows, key=lambda item: (item['dataset_id'], item['name_sha256'], item['reason_code'], item['target_field_id']))), 'corrected_binding_count': len(corrected_binding_pairs), 'corrected_bindings_sha256': sha256_json(sorted(corrected_binding_pairs, key=lambda item: (item['dataset_id'], item['field_id'], item['proposed_id_sha256'], item['proposed_column_sha256']))), 'compiler_owned_dataset_template_count': len(applied_dataset_templates), 'compiler_owned_dataset_templates_sha256': sha256_json(sorted(applied_dataset_templates, key=lambda item: item['dataset_id'])), 'completed_fields_sha256': sha256_json(sorted(completed_pairs, key=lambda item: (item['dataset_id'], item['field_id']))), 'normalized_fields_sha256': sha256_json(sorted(normalized_pairs, key=lambda item: (item['dataset_id'], item['field_id'])))}
    if isinstance(reconciliation_out, dict):
        reconciliation_out.clear()
        reconciliation_out.update(evidence)
    return {'datasets': {key: datasets[key] for key in sorted(datasets)}}

def _validate_bootstrap_fragment(fragment, kind, dataset_descriptors=None, semantic_vocabulary=None, reconciliation_out=None, main_filter_reconciliation_out=None, domain_already_expanded=False):
    if kind == 'domain' and domain_already_expanded:
        expected = set(BOOTSTRAP_FRAGMENT_SECTIONS['domain'])
        if not isinstance(fragment, dict) or set(fragment) != expected:
            raise ContractError('metadata_schema_error', 'metadata_semantic_templates', '승인 도메인 템플릿 확장 결과의 root 계약이 닫혀 있지 않습니다.')
        return deepcopy(fragment)
    schema = _bootstrap_fragment_draft_schema(kind)
    errors = sorted(Draft202012Validator(schema).iter_errors(fragment), key=lambda item: list(item.absolute_path))
    if errors:
        first = errors[0]
        path = '.'.join((str(part) for part in first.absolute_path)) or '$'
        raise ContractError('metadata_schema_error', 'metadata_authoring', '분할 초기 등록 제안 조각이 폐쇄형 소유권 계약과 일치하지 않습니다.', {'authoring_branch': kind, 'path': path, 'reason': first.message[:400]})
    if kind == 'dataset':
        return _expand_compact_dataset_fragment(fragment, dataset_descriptors=dataset_descriptors, reconciliation_out=reconciliation_out)
    if kind == 'main_filter':
        return _expand_compact_main_filter_fragment(fragment, approved_semantic_vocabulary=semantic_vocabulary, reconciliation_out=main_filter_reconciliation_out)
    return deepcopy(fragment)

def _merge_bootstrap_fragments(fragments, dataset_descriptors=None, semantic_vocabulary=None, reconciliation_out=None, main_filter_reconciliation_out=None, domain_already_expanded=False):
    merged = {'contract_version': 'metadata.authoring.draft.v1'}
    section_owners = {}
    merged_aliases = {}
    alias_owners = {}
    for kind in BOOTSTRAP_BRANCH_ORDER:
        fragment = _validate_bootstrap_fragment(fragments.get(kind), kind, dataset_descriptors=dataset_descriptors if kind == 'dataset' else None, semantic_vocabulary=semantic_vocabulary if kind == 'main_filter' else None, reconciliation_out=reconciliation_out if kind == 'dataset' else None, main_filter_reconciliation_out=main_filter_reconciliation_out if kind == 'main_filter' else None, domain_already_expanded=bool(domain_already_expanded) if kind == 'domain' else False)
        for section in BOOTSTRAP_FRAGMENT_SECTIONS[kind]:
            if section not in fragment:
                continue
            value = fragment[section]
            if section == 'aliases':
                for alias in sorted(value):
                    if alias in merged_aliases and merged_aliases[alias] != value[alias]:
                        merged_aliases[alias] = _merge_natural_alias_card(merged_aliases[alias], value[alias], alias)
                    if alias not in merged_aliases:
                        merged_aliases[alias] = deepcopy(value[alias])
                        alias_owners[alias] = kind
                continue
            if section in merged:
                raise ContractError('metadata_schema_error', 'metadata_authoring', '분할 초기 등록 root section 소유권이 충돌합니다.', {'section': section, 'first_branch': section_owners[section], 'second_branch': kind})
            merged[section] = deepcopy(value)
            section_owners[section] = kind
    if merged_aliases:
        baseline_aliases = fragments.get('domain', {}).get('aliases') if domain_already_expanded and isinstance(fragments.get('domain'), dict) else {}
        merged_aliases, alias_conflict_resolution = _resolve_natural_alias_conflicts(merged_aliases, baseline_aliases if isinstance(baseline_aliases, dict) else {})
        if isinstance(main_filter_reconciliation_out, dict):
            main_filter_reconciliation_out['alias_conflict_resolution'] = alias_conflict_resolution
        merged['aliases'] = {alias: merged_aliases[alias] for alias in sorted(merged_aliases)}
    return merged

def _expand_bootstrap_domain_annotation(annotation, *, semantic_templates, semantic_vocabulary):
    """Attach only operator-approved executable semantics to LLM annotations."""
    annotation_schema = load_schema('metadata-annotation-proposal.schema.json')
    annotation_errors = sorted(Draft202012Validator(annotation_schema).iter_errors(annotation), key=lambda item: (list(item.absolute_path), item.message))
    if annotation_errors:
        exc = annotation_errors[0]
        raise ContractError('metadata_schema_error', 'metadata_authoring', '도메인 자연어 제안은 표시 이름과 설명만 포함해야 합니다.', {'path': list(exc.absolute_path)})
    try:
        templates = _validated_semantic_templates(semantic_templates, semantic_vocabulary)
    except ValueError as exc:
        raise ContractError('metadata_dependency_error', 'metadata_semantic_templates', '승인된 도메인 의미 템플릿이 유효하지 않습니다.') from exc
    fragment = {'display_name': str(annotation['display_name']), 'description': str(annotation['description']), 'locale': str(templates['locale']), 'timezone': str(templates['timezone']), **{section: deepcopy(templates[section]) for section in _SEMANTIC_TEMPLATE_SECTIONS}, 'aliases': deepcopy(templates['aliases']), 'output_profile': deepcopy(templates['planner_policy'])}
    evidence = {'contract_version': 'metadata.domain-template-expansion.v1', 'template_contract_version': templates['contract_version'], 'annotation_sha256': sha256_json(annotation), 'semantic_templates_sha256': sha256_json(templates), 'planner_policy_sha256': sha256_json(templates['planner_policy']), 'section_counts': {section: len(fragment[section]) for section in (*_SEMANTIC_TEMPLATE_SECTIONS, 'aliases')}}
    return (fragment, evidence)

def _deterministic_registry_bootstrap_fragments(registry_context):
    """Build initial Dataset/Main Filter fragments only from the approved registry.

    The compact cards contain no model-owned physical semantics.  They merely
    enumerate the already approved IDs so the existing deterministic expanders
    can create the complete initial package after the one domain annotation call.
    """
    registry = registry_context if isinstance(registry_context, dict) else {}
    descriptors = registry.get('dataset_descriptors')
    vocabulary = registry.get('semantic_vocabulary')
    if not isinstance(descriptors, dict) or not isinstance(vocabulary, dict):
        raise ContractError('metadata_dependency_error', 'metadata_registry_bootstrap', '승인 레지스트리에서 초기 Dataset/Main Filter 조각을 만들 수 없습니다.')
    dataset_cards = []
    for dataset_id in sorted(descriptors):
        descriptor = _validated_dataset_descriptor(dataset_id, descriptors[dataset_id])
        dataset_cards.append({'dataset_id': dataset_id, 'fields': [{'id': field_id, 'col': str(descriptor['fields'][field_id]['physical_column'])} for field_id in sorted(descriptor['fields'])]})
    target_types = {'datasets': 'dataset', 'fields': 'field', 'metrics': 'metric', 'relations': 'relation', 'grains': 'grain', 'predicates': 'predicate', 'recipes': 'recipe', 'entity_groups': 'entity_group'}
    alias_additions = []
    for section, target_type in target_types.items():
        for card in vocabulary.get(section) or []:
            if not isinstance(card, dict):
                continue
            target_id = str(card.get('id') or '').strip()
            expressions = sorted({str(value).strip() for value in card.get('labels') or [] if str(value).strip()})
            if target_id and expressions:
                alias_additions.append({'target_type': target_type, 'target_id': target_id, 'expressions': expressions})
    if not dataset_cards or not alias_additions:
        raise ContractError('metadata_dependency_error', 'metadata_registry_bootstrap', '승인 레지스트리의 초기 Dataset 또는 Main Filter 목록이 비어 있습니다.')
    return ({'dataset_cards': dataset_cards}, {'alias_additions': alias_additions})

def _freeform_draft_root_properties(output_schema):
    for branch in (output_schema or {}).get('oneOf') or []:
        properties = branch.get('properties') if isinstance(branch, dict) else None
        if not isinstance(properties, dict) or (properties.get('status') or {}).get('const') != 'complete':
            continue
        draft_schema = properties.get('draft')
        if isinstance(draft_schema, dict):
            return set((draft_schema.get('properties') or {}).keys())
    return set()

def _normalize_legacy_freeform_proposal_shape(proposal, expected_purpose, output_schema):
    """Accept already-exported v5/v6 item shapes before strict validation.

    The provider-facing schema remains the new small IR.  This adapter exists
    only so older imported Flow JSON and deterministic replay fixtures continue
    to run after an upgrade; it never invents an identity or execution value.
    """
    current = deepcopy(proposal) if isinstance(proposal, dict) else proposal
    if not isinstance(current, dict) or current.get('status') != 'complete':
        return current
    draft = current.get('draft')
    if not isinstance(draft, dict):
        return current
    root_properties = _freeform_draft_root_properties(output_schema)
    if expected_purpose == 'metadata_main_filter_draft' and root_properties == {'items'}:
        additions = draft.get('alias_additions')
        if isinstance(additions, list) and set(draft) == {'alias_additions'}:
            items = []
            for addition in additions:
                if not isinstance(addition, dict) or addition.get('target_type') != 'field' or (not str(addition.get('target_id') or '')) or (not isinstance(addition.get('expressions'), list)):
                    return current
                items.append({'filter_key': str(addition['target_id']), 'payload': {'aliases': deepcopy(addition['expressions'])}})
            current['draft'] = {'items': items}
    elif expected_purpose == 'metadata_dataset_draft' and root_properties == {'dataset_cards'}:
        datasets = draft.get('datasets')
        if isinstance(datasets, dict) and set(draft) == {'datasets'}:
            cards = []
            for dataset_id in sorted(datasets):
                dataset = datasets[dataset_id]
                fields = dataset.get('fields') if isinstance(dataset, dict) else None
                if not isinstance(fields, dict):
                    return current
                card = {'dataset_id': str(dataset_id), 'fields': []}
                for name in ('display_name', 'family', 'source_type', 'time_scope', 'selection_criteria', 'default_detail_fields'):
                    if name in dataset:
                        card[name] = deepcopy(dataset[name])
                for field_id in sorted(fields):
                    binding = fields[field_id]
                    if not isinstance(binding, dict) or not str(binding.get('physical_column') or ''):
                        return current
                    field = {'id': str(field_id), 'col': str(binding['physical_column'])}
                    for name in ('semantic_type', 'roles', 'aliases', 'unit'):
                        if name in binding:
                            field[name] = deepcopy(binding[name])
                    card['fields'].append(field)
                cards.append(card)
            current['draft'] = {'dataset_cards': cards}
    elif expected_purpose == 'metadata_domain_draft' and root_properties == {'items'}:
        items = []
        if set(draft) <= {'domain_id', 'display_name', 'description', 'locale', 'timezone'} and draft.get('display_name'):
            key = str(draft.get('domain_id') or 'default')
            payload = {name: deepcopy(draft[name]) for name in ('display_name', 'description', 'locale', 'timezone') if name in draft}
            items.append({'section': 'profile', 'key': key, 'payload': payload})
        elif set(draft) == {'entity_groups'} and isinstance(draft.get('entity_groups'), dict):
            for key in sorted(draft['entity_groups']):
                items.append({'section': 'entity_groups', 'key': str(key), 'payload': deepcopy(draft['entity_groups'][key])})
        if items:
            current['draft'] = {'items': items}
    return current

def _freeform_sentence_value(source_text, labels):
    """Read one short worker-facing value without depending on LLM JSON."""
    label_pattern = '|'.join(labels)
    match = re.search(f'(?im)(?:{label_pattern})\\s*(?:은|는|:|=)\\s*([^\\r\\n.]+)', str(source_text or ''))
    if match is None:
        return ''
    value = match.group(1).strip(' \t\r\n.\'"')
    value = re.split('\\s*(?:이고|이며)\\s+(?=유의어|별칭|설명|description)', value, maxsplit=1)[0]
    value = re.sub('\\s*(?:이면\\s*(?:돼|됩니다?)|이면\\s*돼요|이야|입니다?|로\\s*(?:해줘|저장해줘))\\s*$', '', value).strip()
    return value

def _freeform_dataset_id(source_text):
    matches = re.findall('(?im)(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*(?:으)?로\\s*등록(?:해줘|합니다?|하세요|할게)?', str(source_text or ''))
    values = list(dict.fromkeys(matches))
    return values[0] if len(values) == 1 else ''

def _freeform_domain_group_card(source_text):
    text = str(source_text or '')
    group_match = re.search('(?im)(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*공정\\s*그룹(?:을|를)?\\s*등록', text)
    field_match = re.search('(?im)(?<![A-Za-z0-9_])field(?![A-Za-z0-9_])\\s*(?:은|는|:|=)\\s*([A-Za-z][A-Za-z0-9_.-]{0,127})', text)
    aliases_match = re.search('(?im)유의어\\s*(?:은|는|:|=)\\s*([^\\r\\n.]+)', text)
    members_match = re.search('(?im)포함\\s*공정\\s*(?:은|는|:|=)\\s*(?:[A-Za-z][A-Za-z0-9_.-]{0,127}\\s*값\\s*)?([^\\r\\n.]+)', text)
    if not all((group_match, field_match, aliases_match, members_match)):
        return None
    group_id = group_match.group(1)
    aliases = _freeform_csv_values(re.sub('\\s*(?:이야|입니다?|로\\s*저장해줘)\\s*$', '', aliases_match.group(1)))
    members = _freeform_csv_values(re.sub('\\s*(?:이야|입니다?|로\\s*저장해줘)\\s*$', '', members_match.group(1)))
    if not aliases or not members:
        return None
    display_name = _freeform_sentence_value(text, ('display_name', '화면(?:에\\s*보일)?\\s*이름')) or group_id
    return {'section': 'entity_groups', 'key': group_id, 'payload': {'display_name': display_name, 'field': field_match.group(1), 'processes': members, 'aliases': aliases}}

def _freeform_domain_profile_card(source_text):
    text = str(source_text or '')
    match = re.search('(?im)(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*도메인(?:으)?로\\s*등록', text)
    if match is None:
        return None
    domain_id = match.group(1)
    display_name = _freeform_sentence_value(text, ('display_name', '화면(?:에\\s*보일)?\\s*이름')) or domain_id
    payload = {'display_name': display_name}
    locale = re.search('(?im)언어\\s*(?:은|는|:|=)\\s*([A-Za-z]{2}-[A-Za-z]{2})', text)
    timezone_match = re.search('(?im)시간대\\s*(?:은|는|:|=)\\s*([A-Za-z]+/[A-Za-z_]+)', text)
    if locale:
        payload['locale'] = locale.group(1)
    if timezone_match:
        payload['timezone'] = timezone_match.group(1)
    return {'section': 'profile', 'key': domain_id, 'payload': payload}

def _freeform_domain_grain_card(source_text):
    text = str(source_text or '')
    if re.search('(?:recipe|레시피)', text, flags=re.IGNORECASE):
        return None
    match = re.search('(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*grain', text, flags=re.IGNORECASE)
    keys = _freeform_recipe_keys({}, text)
    if match is None or not keys:
        return None
    return {'section': 'grains', 'key': match.group(1), 'payload': {'grain_keys': keys}}

def _freeform_domain_recipe_card(source_text):
    text = str(source_text or '')
    if not re.search('(?:recipe|레시피)', text, flags=re.IGNORECASE):
        return None
    recipe_id = _freeform_recipe_identity('', {}, text)
    keys = _freeform_recipe_keys({}, text)
    grain_match = re.search('grain\\s*(?:은|는|:|=|is)\\s*([A-Za-z][A-Za-z0-9_.-]*)', text, flags=re.IGNORECASE)
    if not recipe_id or not keys or grain_match is None:
        return None
    aliases_match = re.search('유의어\\s*(?:은|는|:|=)\\s*([^\\r\\n.]+)', text, flags=re.IGNORECASE)
    aliases = []
    if aliases_match:
        aliases = _freeform_csv_values(re.sub('\\s*(?:이야|입니다)\\s*$', '', aliases_match.group(1)))
    return {'section': 'recipes', 'key': recipe_id, 'payload': {'aliases': aliases, 'grain': grain_match.group(1), 'grain_keys': keys, 'required_slots': ['dataset', 'metric']}}

def _freeform_main_filter_cards(source_text):
    text = str(source_text or '')
    marker = re.compile('(?im)(?<![A-Za-z0-9_.-])([A-Za-z][A-Za-z0-9_.-]{0,127})\\s*(?:을|를|도)?\\s*(?:주요\\s*조회\\s*조건|main\\s*filter)(?:으)?로\\s*(?:등록|저장)')
    matches = list(marker.finditer(text))
    cards = []
    for index, match in enumerate(matches):
        segment = text[match.start():matches[index + 1].start() if index + 1 < len(matches) else len(text)]
        aliases_match = re.search('(?im)유의어\\s*(?:은|는|:|=)\\s*([^\\r\\n.]+)', segment)
        if aliases_match is None:
            continue
        alias_text = re.sub('\\s*(?:이야|입니다?|로\\s*저장해줘)\\s*$', '', aliases_match.group(1))
        alias_text = re.sub('(?<=[A-Za-z0-9_])야\\s*$', '', alias_text)
        aliases = _freeform_csv_values(alias_text)
        if not aliases:
            continue
        payload = {'aliases': aliases}
        display_name = _freeform_sentence_value(segment, ('display_name', '화면(?:에\\s*보일)?\\s*이름'))
        if display_name:
            payload['display_name'] = display_name
        cards.append({'filter_key': match.group(1), 'payload': payload})
    return cards

def _deterministic_freeform_authoring_proposal(component, expected_purpose, output_schema):
    """Project common v5-style worker text into the small IR.

    This is deliberately narrower than an LLM: it activates only when the
    worker explicitly names the item identity and the values needed for safe
    execution. Unsupported prose continues through the schema-bound LLM path.
    """
    root_properties = _freeform_draft_root_properties(output_schema)
    expected_root = {'metadata_domain_draft': {'items'}, 'metadata_dataset_draft': {'dataset_cards'}, 'metadata_main_filter_draft': {'items'}}.get(expected_purpose)
    if expected_root is None or root_properties != expected_root:
        return None
    source_text = _authoring_source_text(component)
    if not source_text:
        return None
    if expected_purpose == 'metadata_dataset_draft':
        dataset_id = _freeform_dataset_id(source_text)
        family = _freeform_dataset_family(source_text, dataset_id) or dataset_id if dataset_id else ''
        source_type = _freeform_source_type(source_text)
        if not dataset_id or not family or (not source_type) or (not (_freeform_filter_mappings(source_text) or _freeform_query_columns(source_text))):
            return None
        card = {'dataset_id': dataset_id, 'display_name': _freeform_sentence_value(source_text, ('display_name', '화면(?:에\\s*보일)?\\s*이름')) or dataset_id, 'family': family, 'source_type': source_type, 'fields': []}
        selection = _freeform_selection_criteria(source_text)
        if selection:
            card['selection_criteria'] = selection
            if selection.get('time_scope'):
                card['time_scope'] = selection['time_scope']
        draft = {'dataset_cards': [card]}
    elif expected_purpose == 'metadata_domain_draft':
        item = _freeform_domain_recipe_card(source_text) or _freeform_domain_grain_card(source_text) or _freeform_domain_group_card(source_text) or _freeform_domain_profile_card(source_text)
        if item is None:
            return None
        draft = {'items': [item]}
    else:
        items = _freeform_main_filter_cards(source_text)
        if not items:
            return None
        draft = {'items': items}
    proposal = {'contract_version': 'metadata.authoring.proposal.v1', 'status': 'complete', 'source_sha256': hashlib.sha256(source_text.encode('utf-8')).hexdigest(), 'draft': draft}
    if output_schema is not None and any(Draft202012Validator(output_schema).iter_errors(proposal)):
        return None
    component._observed_authoring_source_projection = {'contract_version': 'metadata.deterministic-source-projection.v1', 'purpose': expected_purpose, 'status': 'used', 'source_sha256': proposal['source_sha256'], 'draft_sha256': sha256_json(draft)}
    return proposal

def _authoring_invocation_draft(component, *, input_name, expected_purpose, required, expected_output_schema=None, expected_runtime_context_sha256=''):
    raw = getattr(component, input_name, None)
    invocation = getattr(raw, 'data', raw)
    invocation = invocation if isinstance(invocation, dict) else {}
    calls = int(invocation.get('llm_calls') or 0) if invocation else 0
    usage = deepcopy(getattr(component, '_observed_authoring_llm_usage', None) or {})
    usage.setdefault('draft_llm_calls', 0)
    usage.setdefault('annotation_llm_calls', 0)
    bucket = 'annotation_llm_calls' if expected_purpose == 'metadata_domain_annotation' else 'draft_llm_calls'
    usage[bucket] = int(usage.get(bucket) or 0) + calls
    usage['repair_llm_calls'] = 0
    component._observed_authoring_llm_usage = usage
    if not required:
        if calls != 0:
            raise ContractError('metadata_policy_error', 'metadata_llm_boundary', '결정론적 등록 분기에서 LLM이 호출되었습니다.', {'input_name': input_name, 'expected_purpose': expected_purpose, 'llm_calls': calls})
        return None
    deterministic_proposal = _deterministic_freeform_authoring_proposal(component, expected_purpose, expected_output_schema)
    if deterministic_proposal is not None:
        return deterministic_proposal
    if invocation.get('contract_version') != 'llm.invocation.v1' or invocation.get('purpose') != expected_purpose or invocation.get('status') != 'ok' or (calls != 1):
        invocation_error = invocation.get('error') if isinstance(invocation.get('error'), dict) else {}
        provider_error_type = str(invocation_error.get('provider_error_type') or '')[:80]
        if not provider_error_type.isidentifier():
            provider_error_type = ''
        provider_error_status = str(invocation_error.get('provider_error_status') or '')[:80]
        if not re.fullmatch('[A-Za-z0-9._-]{1,80}', provider_error_status):
            provider_error_status = ''
        provider_error_code = str(invocation_error.get('provider_error_code') or '')[:80]
        if not re.fullmatch('[A-Za-z0-9._-]{1,80}', provider_error_code):
            provider_error_code = ''
        provider_binding = str(invocation.get('provider_schema_binding') or '')[:80]
        if not re.fullmatch('[a-z][a-z0-9_]{0,79}', provider_binding):
            provider_binding = ''
        raise ContractError('metadata_llm_unavailable', 'metadata_draft', '외부 Prompt/LLM 노드의 검증된 단일 호출 결과가 필요합니다.', {'input_name': input_name, 'expected_purpose': expected_purpose, 'llm_calls': calls, 'error_type': provider_error_type, 'reason': provider_error_status, 'provider_error_code': provider_error_code, 'provider_schema_binding': provider_binding, 'invocation_error_code': str(invocation_error.get('code') or '')[:80]})
    prompt_bundle_sha256 = str(invocation.get('prompt_bundle_sha256') or '')
    runtime_context_sha256 = str(invocation.get('runtime_context_sha256') or '')
    if not re.fullmatch('[0-9a-f]{64}', prompt_bundle_sha256):
        raise ContractError('metadata_dependency_error', 'metadata_llm_prompt_binding', 'LLM invocation prompt bundle evidence is invalid.', {'input_name': input_name, 'expected_purpose': expected_purpose})
    if expected_runtime_context_sha256:
        if not re.fullmatch('[0-9a-f]{64}', str(expected_runtime_context_sha256)) or runtime_context_sha256 != expected_runtime_context_sha256:
            raise ContractError('metadata_dependency_error', 'metadata_llm_prompt_binding', 'LLM invocation runtime context evidence does not match the authoritative context.', {'input_name': input_name, 'expected_purpose': expected_purpose})
    if expected_output_schema is not None:
        expected_schema_sha256 = sha256_json(expected_output_schema)
        evidence = invocation.get('schema_binding_evidence')
        binding_status = str(evidence.get('binding_status') or '') if isinstance(evidence, dict) else ''
        provider_binding = str(invocation.get('provider_schema_binding') or '')
        provider_schema_sha256 = str(evidence.get('provider_schema_sha256') or '') if isinstance(evidence, dict) else ''
        projection = str(evidence.get('projection') or '') if isinstance(evidence, dict) else ''
        google_projection_valid = binding_status == 'google_native_json_schema' and projection == 'google_supported_json_schema_subset.v6' and bool(re.fullmatch('[0-9a-f]{64}', provider_schema_sha256))
        portable_projection_valid = binding_status == 'portable_prompt_and_compiler_validation' and projection == 'none' and (provider_schema_sha256 == '')
        if not isinstance(evidence, dict) or set(evidence) != {'contract_version', 'binding_status', 'projection', 'authoritative_schema_sha256', 'provider_schema_sha256'} or evidence.get('contract_version') != 'llm.schema-binding.evidence.v1' or (provider_binding != binding_status) or (evidence.get('authoritative_schema_sha256') != expected_schema_sha256) or (not (google_projection_valid or portable_projection_valid)):
            raise ContractError('metadata_dependency_error', 'metadata_llm_schema_binding', 'LLM 호출의 스키마 결합 증적이 authoritative runtime schema와 일치하지 않습니다.', {'input_name': input_name, 'expected_purpose': expected_purpose, 'expected_schema_sha256': expected_schema_sha256, 'binding_status': binding_status})
    response_text = str(invocation.get('response_text') or '')
    response_bytes = len(response_text.encode('utf-8'))
    observed_response_sha256 = hashlib.sha256(response_text.encode('utf-8')).hexdigest()
    if invocation.get('response_sha256') != observed_response_sha256:
        raise ContractError('metadata_dependency_error', 'metadata_llm_response_binding', 'LLM invocation response hash does not match the response body.', {'input_name': input_name, 'expected_purpose': expected_purpose, 'response_bytes': response_bytes})
    try:
