        if schema_errors:
            root_error = schema_errors[0]
            candidates = []
            pending = [root_error]
            while pending:
                candidate = pending.pop()
                candidates.append(candidate)
                pending.extend(list(candidate.context or []))
            exc = max(candidates, key=lambda item: (len(list(item.absolute_path)), 1 if str(item.validator or '') in {'required', 'additionalProperties'} else 0, -len(str(item.message or ''))))
