_CLARIFICATION_TECHNICAL_PATTERN = re.compile('(?:canonical|dataset[ _-]?id|field[ _-]?id|physical(?:[ _-]?column)?|semantic(?:[ _-]?type)?|json|dsl|config_ref|query_ref|schema|source[ _-]?registry|registry|물리\\s*컬럼|시맨틱\\s*타입|기술\\s*문법|내부\\s*ID|레지스트리|스키마)', re.IGNORECASE)

_GENERIC_BUSINESS_CLARIFICATION = '어떤 업무 데이터나 수치를 뜻하는지 자연어로 설명해 주세요.'

def _worker_safe_clarification(questions, missing_fields):
    safe_questions = []
    for raw_question in questions if isinstance(questions, list) else []:
        question = re.sub('\\s+', ' ', str(raw_question or '').strip())
        if not question:
            continue
        if _CLARIFICATION_TECHNICAL_PATTERN.search(question):
            question = _GENERIC_BUSINESS_CLARIFICATION
        if question not in safe_questions:
            safe_questions.append(question[:400])
        if len(safe_questions) == 3:
            break
    if not safe_questions:
        safe_questions = [_GENERIC_BUSINESS_CLARIFICATION]
    safe_missing = []
    for raw_field in missing_fields if isinstance(missing_fields, list) else []:
        token = str(raw_field or '').casefold()
        if any((marker in token for marker in ('metric', 'formula', '수치', '계산'))):
            label = '업무 수치 설명'
        elif any((marker in token for marker in ('relation', 'join', '관계', '연결'))):
            label = '업무 데이터 관계 설명'
        elif any((marker in token for marker in ('filter', 'alias', 'predicate', '조건', '별칭'))):
            label = '조회 조건 설명'
        else:
            label = '업무 데이터 설명'
        if label not in safe_missing:
            safe_missing.append(label)
    if not safe_missing:
        safe_missing = ['업무 데이터 설명']
    return (safe_questions, safe_missing)

def _unwrap_freeform_authoring_proposal(raw_proposal, *, source_sha256):
    """Validate the model's two-state proposal and return its complete draft.

    This gate deliberately runs before the metadata compiler and before any
    MongoDB write.  A worker may write arbitrary prose; the model may either
    produce one closed candidate or ask up to three factual questions.  It may
    never emit a partial candidate that silently enters the approval path.
    """
    proposal = deepcopy(raw_proposal) if isinstance(raw_proposal, dict) else {}
    status = str(proposal.get('status') or '')
    expected_source_sha256 = str(source_sha256 or '')
    common_keys = {'contract_version', 'status', 'source_sha256'}
    if proposal.get('contract_version') != 'metadata.authoring.proposal.v1' or not re.fullmatch('[0-9a-f]{64}', expected_source_sha256) or proposal.get('source_sha256') != expected_source_sha256:
        raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '자유형 자연어 등록 제안이 원문 SHA-256과 결합되지 않았습니다.', {'expected_source_sha256': expected_source_sha256})
    proposal_sha256 = sha256_json(proposal)
    if status == 'complete':
        if set(proposal) != common_keys | {'draft'} or not isinstance(proposal.get('draft'), dict):
            raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '완료 제안은 폐쇄형 draft 하나만 포함해야 합니다.')
        draft = deepcopy(proposal['draft'])
        evidence = {'contract_version': 'metadata.authoring.proposal.validation.v1', 'proposal_contract_version': 'metadata.authoring.proposal.v1', 'status': 'complete', 'source_sha256': expected_source_sha256, 'proposal_sha256': proposal_sha256, 'draft_sha256': sha256_json(draft)}
        return (draft, evidence)
    if status == 'needs_clarification':
        if set(proposal) != common_keys | {'clarification'}:
            raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '확인 질문 제안에는 draft 또는 저장 후보 필드를 포함할 수 없습니다.')
        clarification = proposal.get('clarification')
        if not isinstance(clarification, dict) or set(clarification) != {'questions', 'missing_fields'}:
            raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '확인 질문 payload가 폐쇄형 계약과 일치하지 않습니다.')
        questions = clarification.get('questions')
        missing_fields = clarification.get('missing_fields')
        if not isinstance(questions, list) or not 1 <= len(questions) <= 3 or len(set(questions)) != len(questions) or any((not isinstance(item, str) or not item.strip() or len(item) > 400 for item in questions)) or (not isinstance(missing_fields, list)) or (len(missing_fields) > 32) or (len(set(missing_fields)) != len(missing_fields)) or any((not isinstance(item, str) or not item.strip() or len(item) > 128 for item in missing_fields)):
            raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '확인 질문의 개수 또는 길이가 허용 범위를 벗어났습니다.')
        raise ContractError('metadata_clarification_required', 'metadata_clarification', '메타데이터를 추측하지 않고 작업자 확인이 필요한 항목을 반환했습니다.', {'contract_version': 'metadata.authoring.clarification.v1', 'questions': [item.strip() for item in questions], 'missing_fields': [item.strip() for item in missing_fields], 'source_sha256': expected_source_sha256, 'proposal_sha256': proposal_sha256})
    raise ContractError('metadata_schema_error', 'metadata_authoring_proposal', '자유형 자연어 등록 제안 status가 유효하지 않습니다.', {'status': status})

def _unwrap_bootstrap_authoring_proposal(raw_proposal, *, kind, source_sha256, composite_source_sha256):
    try:
        return _unwrap_freeform_authoring_proposal(raw_proposal, source_sha256=source_sha256)
    except ContractError as exc:
        if exc.code != 'metadata_clarification_required' or not isinstance(exc.details, dict):
            raise
        details = deepcopy(exc.details)
        questions = list(details.get('questions') or [])
        branch_label = {'domain': '업무 정의', 'dataset': '업무 데이터', 'main_filter': '조회 조건'}.get(kind, '업무 설명')
        details['questions'] = [f'[{branch_label} {index}] {question}'[:400] for index, question in enumerate(questions, start=1)]
        details['missing_fields'] = [f'{branch_label}: {field}'[:128] for field in list(details.get('missing_fields') or [])]
        original_proposal_sha256 = str(details.get('proposal_sha256') or '')
        details['source_sha256'] = composite_source_sha256
        details['proposal_sha256'] = sha256_json({'authoring_branch': kind, 'proposal_sha256': original_proposal_sha256})
        raise ContractError(exc.code, exc.stage, exc.public_message, details, exc.retryable) from exc

def _enforce_domain_policy_boundary(draft, *, source_sha256, proposal_sha256='', grounding_mode='freeform_llm', approved_planner_policy=None):
    """Keep prompt/function/output policy exclusively owned by Domain Policy Flow."""
    current = deepcopy(draft) if isinstance(draft, dict) else {}
    prompt_extensions = current.get('prompt_extensions')
    specialized_functions = current.get('specialized_functions')
    output_profile = current.get('output_profile')
    sealed_planner_policy = deepcopy(approved_planner_policy) if isinstance(approved_planner_policy, dict) else {}
    non_empty_prompt = isinstance(prompt_extensions, dict) and any((str(prompt_extensions.get(key) or '').strip() for key in ('intent', 'answer')))
    if non_empty_prompt or specialized_functions not in (None, []) or (output_profile not in (None, {}) and output_profile != sealed_planner_policy):
        raise ContractError('metadata_policy_error', 'metadata_domain_policy_boundary', '도메인 자연어 LLM은 특화 프롬프트, 등록 함수 또는 출력 정책을 작성할 수 없습니다. Domain Policy Flow를 사용하세요.')
    current['prompt_extensions'] = {'intent': '', 'answer': ''}
    current['specialized_functions'] = []
    current['output_profile'] = sealed_planner_policy
    current['source_provenance'] = {'source_sha256': str(source_sha256 or ''), 'grounding_mode': str(grounding_mode or 'freeform_llm'), 'proposal_sha256': str(proposal_sha256 or '')}
    return current

def _complete_unambiguous_metric_bindings(draft, approved_semantic_vocabulary=None):
    """Expand only exact ``<dataset_family>.<field>`` refs; never infer or repair."""
    current = deepcopy(draft) if isinstance(draft, dict) else {}
    datasets = current.get('datasets')
    metrics = current.get('metrics')
    vocabulary = approved_semantic_vocabulary if isinstance(approved_semantic_vocabulary, dict) else {}
    completed = []
    preserved = []
    if not isinstance(datasets, dict) or not isinstance(metrics, dict):
        metrics = {}
    vocabulary_metric_ids = [card.get('id') for card in vocabulary.get('metrics') or [] if isinstance(card, dict)]
    vocabulary_fields = [card for card in vocabulary.get('fields') or [] if isinstance(card, dict)]
    draft_candidates = {(str(card.get('family') or ''), str(field_id)) for card in (datasets or {}).values() if isinstance(card, dict) for field_id in (card.get('fields') or {} if isinstance(card.get('fields'), dict) else {})}
    for metric_id, raw_metric in metrics.items():
        if not isinstance(raw_metric, dict):
            continue
        existing_binding = raw_metric.get('source_binding')
        if isinstance(existing_binding, dict):
            preserved.append(str(metric_id))
            continue
        if existing_binding is None:
            continue
        if not isinstance(existing_binding, str):
            continue
        semantic_candidates = []
        if vocabulary_metric_ids.count(metric_id) == 1:
            for field_card in vocabulary_fields:
                field_id = field_card.get('id')
                for family in field_card.get('families') or []:
                    if existing_binding == f'{family}.{field_id}':
                        semantic_candidates.append((str(family), str(field_id)))
        candidates = sorted({candidate for candidate in semantic_candidates if candidate in draft_candidates})
        if len(candidates) != 1:
            raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', '지표 원천 참조가 승인된 의미 필드 하나로 정확히 결정되지 않습니다.', {'metric_id_sha256': sha256_json(str(metric_id)), 'source_binding_sha256': sha256_json(existing_binding), 'candidate_count': len(candidates)})
        family, field_id = candidates[0]
        raw_metric['source_binding'] = {'dataset_family': family, 'field': field_id}
        completed.append(str(metric_id))
    completed = sorted(completed)
    preserved = sorted(preserved)
    return (current, {'contract_version': 'metadata.metric-binding-reconciliation.v1', 'resolution_mode': 'approved_semantic_vocabulary_exact', 'completed_count': len(completed), 'completed_metric_ids_sha256': sha256_json(completed), 'corrected_count': 0, 'corrected_metric_ids_sha256': sha256_json([]), 'preserved_full_card_count': len(preserved), 'preserved_full_card_ids_sha256': sha256_json(preserved)})

_SEMANTIC_ALIAS_TARGET_SECTIONS = (('datasets', 'dataset'), ('fields', 'field'), ('metrics', 'metric'), ('relations', 'relation'), ('grains', 'grain'), ('predicates', 'predicate'), ('recipes', 'recipe'), ('entity_groups', 'entity_group'))

_NATURAL_ALIAS_POLICY = {'normalization': ['unicode_nfkc', 'trim', 'collapse_space', 'latin_casefold'], 'match': 'bounded_longest', 'conflict': 'fail_ambiguous', 'provenance_source': 'natural_authoring'}

def _semantic_alias_target_candidates(draft, vocabulary, target_id):
    candidates = []
    datasets = draft.get('datasets') if isinstance(draft, dict) else {}
    for section, target_type in _SEMANTIC_ALIAS_TARGET_SECTIONS:
        cards = vocabulary.get(section) if isinstance(vocabulary, dict) else []
        matches = [card for card in cards or [] if isinstance(card, dict) and card.get('id') == target_id]
        if not matches:
            continue
        if section == 'datasets':
            registered = isinstance(datasets, dict) and target_id in datasets
        elif section == 'fields':
            registered = any((isinstance(dataset, dict) and isinstance(dataset.get('fields'), dict) and (target_id in dataset['fields']) for dataset in (datasets or {}).values()))
        else:
            registered = isinstance(draft.get(section), dict) and target_id in draft[section]
        if registered:
            candidates.extend(((target_type, target_id) for _ in matches))
    return candidates

def _normalized_natural_alias_expressions(expressions, target_id):
    if not isinstance(expressions, list) or not 1 <= len(expressions) <= 64:
        raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', '자연어 별칭 표현은 bounded non-empty list여야 합니다.', {'target_id_sha256': sha256_json(str(target_id)), 'expression_count': len(expressions) if isinstance(expressions, list) else 0})
    forbidden = ('http://', 'https://', 'mongodb://', 'mongodb+srv://', 'select ', 'insert ', 'update ', 'delete ', 'password', 'secret', 'token=', 'api_key')
    result = {}
    for raw_expression in expressions:
        if not isinstance(raw_expression, str):
            raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', '자연어 별칭 표현은 text여야 합니다.', {'target_id_sha256': sha256_json(str(target_id))})
        expression = re.sub('\\s+', ' ', unicodedata.normalize('NFKC', raw_expression).strip())
        folded = expression.casefold()
        if not expression or len(expression.encode('utf-8')) > 512 or any((ord(character) < 32 for character in expression)) or any((fragment in folded for fragment in forbidden)):
            raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', '자연어 별칭 표현이 비어 있거나 허용 범위를 벗어났습니다.', {'target_id_sha256': sha256_json(str(target_id))})
        result.setdefault(folded, expression)
    return [result[key] for key in sorted(result, key=lambda key: (key, result[key]))]

def _alias_value_text(value):
    if isinstance(value, str):
        return value
    if isinstance(value, dict) and set(value) == {'text', 'priority'}:
        text = value.get('text')
        priority = value.get('priority')
        if isinstance(text, str) and isinstance(priority, int) and (not isinstance(priority, bool)):
            return text
    return None

def _merge_natural_alias_card(existing, generated, canonical_key):
    identity_keys = {'target_type', 'target_key'}
    policy_keys = {'normalization', 'match', 'conflict'}
    if not isinstance(existing, dict) or any((existing.get(key) != generated.get(key) for key in identity_keys)) or any((key in existing and existing.get(key) != generated.get(key) for key in policy_keys)) or (not isinstance(existing.get('values'), list)):
        raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', 'canonical alias card가 다른 대상 또는 정책과 충돌합니다.', {'alias_key_sha256': sha256_json(canonical_key)})
    merged = deepcopy(existing)
    seen = set()
    for value in merged['values']:
        text = _alias_value_text(value)
        if text is None:
            raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', '기존 canonical alias value가 유효하지 않습니다.', {'alias_key_sha256': sha256_json(canonical_key)})
        normalized = re.sub('\\s+', ' ', unicodedata.normalize('NFKC', text).strip())
        seen.add(normalized.casefold())
    append_as_strings = bool(merged['values']) and all((isinstance(value, str) for value in merged['values']))
    for value in generated['values']:
        marker = value['text'].casefold()
        if marker not in seen:
            seen.add(marker)
            merged['values'].append(value['text'] if append_as_strings else value)
    return merged

def _resolve_natural_alias_conflicts(candidate_aliases, baseline_aliases):
    """Preserve approved aliases and discard ambiguous natural additions."""
    if not isinstance(candidate_aliases, dict) or not isinstance(baseline_aliases, dict):
        raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', 'Alias conflict inputs must be closed dictionaries.')

    def marker(value):
        text = _alias_value_text(value)
        if text is None:
            return ''
        return re.sub('\\s+', ' ', unicodedata.normalize('NFKC', text).strip()).casefold()
    baseline_targets = {}
    baseline_markers_by_key = {}
    for canonical_key, card in sorted(baseline_aliases.items()):
        values = card.get('values') if isinstance(card, dict) else None
        if not isinstance(values, list):
            raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', 'Approved baseline alias card is invalid.', {'alias_key_sha256': sha256_json(str(canonical_key))})
        markers = {marker(value) for value in values}
        if '' in markers:
            raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', 'Approved baseline alias value is invalid.', {'alias_key_sha256': sha256_json(str(canonical_key))})
        baseline_markers_by_key[canonical_key] = markers
        for normalized in markers:
            baseline_targets.setdefault(normalized, set()).add(canonical_key)
    delta_rows = []
    redundant_count = 0
    for canonical_key, card in sorted(candidate_aliases.items()):
        values = card.get('values') if isinstance(card, dict) else None
        if not isinstance(values, list):
            raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', 'Candidate alias card is invalid.', {'alias_key_sha256': sha256_json(str(canonical_key))})
        same_target_baseline = baseline_markers_by_key.get(canonical_key, set())
        for value in values:
            normalized = marker(value)
            if not normalized:
                raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', 'Candidate alias value is invalid.', {'alias_key_sha256': sha256_json(str(canonical_key))})
            if normalized in same_target_baseline:
                if canonical_key not in baseline_aliases or value not in baseline_aliases[canonical_key]['values']:
                    redundant_count += 1
                continue
            delta_rows.append((canonical_key, normalized, deepcopy(value)))
    delta_targets = {}
    for canonical_key, normalized, _ in delta_rows:
        delta_targets.setdefault(normalized, set()).add(canonical_key)
    accepted_by_key = {}
    discarded_baseline_conflict_count = 0
    discarded_cross_target_count = 0
    duplicate_same_target_count = 0
    seen_by_key = {}
    for canonical_key, normalized, value in sorted(delta_rows, key=lambda row: (row[0], row[1], sha256_json(row[2]))):
        approved_targets = baseline_targets.get(normalized, set())
        if approved_targets and approved_targets != {canonical_key}:
            discarded_baseline_conflict_count += 1
            continue
        if len(delta_targets.get(normalized, set())) != 1:
            discarded_cross_target_count += 1
            continue
        if normalized in seen_by_key.setdefault(canonical_key, set()):
            duplicate_same_target_count += 1
            continue
        seen_by_key[canonical_key].add(normalized)
        accepted_by_key.setdefault(canonical_key, []).append(value)
    resolved = {key: deepcopy(card) for key, card in sorted(baseline_aliases.items())}
    for canonical_key, card in sorted(candidate_aliases.items()):
        accepted = accepted_by_key.get(canonical_key, [])
        if canonical_key in resolved:
            append_as_strings = bool(resolved[canonical_key]['values']) and all((isinstance(value, str) for value in resolved[canonical_key]['values']))
            for value in accepted:
                text = _alias_value_text(value)
                resolved[canonical_key]['values'].append(text if append_as_strings else value)
        elif accepted:
            resolved[canonical_key] = deepcopy(card)
            resolved[canonical_key]['values'] = accepted
    evidence = {'contract_version': 'metadata.alias-conflict-resolution.v1', 'baseline_card_count': len(baseline_aliases), 'candidate_card_count': len(candidate_aliases), 'resolved_card_count': len(resolved), 'accepted_delta_count': sum((len(values) for values in accepted_by_key.values())), 'redundant_delta_count': redundant_count, 'discarded_baseline_conflict_count': discarded_baseline_conflict_count, 'discarded_cross_target_count': discarded_cross_target_count, 'duplicate_same_target_count': duplicate_same_target_count, 'resolved_aliases_sha256': sha256_json(resolved)}
    return (resolved, evidence)

def _expand_compact_main_filter_fragment(fragment, *, approved_semantic_vocabulary, allow_unresolved=False, reconciliation_out=None):
    """Compile typed natural-language alias additions into canonical cards."""
    vocabulary = None
    if approved_semantic_vocabulary:
        try:
            vocabulary = _validated_semantic_vocabulary(approved_semantic_vocabulary)
        except ValueError as exc:
            raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', '승인 축약 업무 어휘가 유효하지 않습니다.') from exc
