def _merge_typed_main_filter_patch(base_draft, expanded_patch):
    """Merge registry-bound alias IR without reinterpreting it as legacy shorthand."""
    if not isinstance(expanded_patch, dict) or set(expanded_patch) != {'aliases'}:
        raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', 'Expanded Main Filter IR must contain only aliases.')
    base_aliases = base_draft.get('aliases') if isinstance(base_draft, dict) else None
    patch_aliases = expanded_patch.get('aliases')
    if not isinstance(base_aliases, dict) or not isinstance(patch_aliases, dict):
        raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', 'Main Filter alias catalogs are unavailable.')
    candidate_aliases = deepcopy(base_aliases)
    for canonical_key in sorted(patch_aliases):
        generated = patch_aliases[canonical_key]
        if canonical_key in base_aliases:
            candidate_aliases[canonical_key] = _merge_natural_alias_card(base_aliases[canonical_key], generated, canonical_key)
        else:
            candidate_aliases[canonical_key] = deepcopy(generated)
    resolved_aliases, _ = _resolve_natural_alias_conflicts(candidate_aliases, base_aliases)
    merged_patch = {canonical_key: resolved_aliases[canonical_key] for canonical_key in sorted(patch_aliases) if canonical_key in resolved_aliases}
    return {'aliases': merged_patch}

def _normalize_bootstrap_alias_shorthand(draft, approved_semantic_vocabulary):
    current = deepcopy(draft) if isinstance(draft, dict) else {}
    aliases = current.get('aliases')
    if aliases is None:
        aliases = {}
    if not isinstance(aliases, dict):
        raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', 'aliases는 object여야 합니다.')
    full_cards = {}
    shorthand = []
    for alias_key in sorted(aliases):
        card = aliases[alias_key]
        if isinstance(card, dict) and 'expressions' in card:
            if set(card) != {'expressions'}:
                raise ContractError('metadata_schema_error', 'metadata_semantic_reference_normalization', '자연어 alias shorthand에 비허용 key가 있습니다.', {'target_id_sha256': sha256_json(str(alias_key))})
            shorthand.append((str(alias_key), card['expressions']))
        else:
            full_cards[str(alias_key)] = deepcopy(card)
    normalized_ids = []
    for target_id, expressions in shorthand:
        candidates = _semantic_alias_target_candidates(current, approved_semantic_vocabulary, target_id)
        if len(candidates) != 1:
            raise ContractError('metadata_dependency_error', 'metadata_semantic_reference_normalization', '자연어 alias 대상이 승인된 draft 대상 하나로 정확히 결정되지 않습니다.', {'target_id_sha256': sha256_json(target_id), 'candidate_count': len(candidates)})
        target_type, target_key = candidates[0]
        canonical_key = f'{target_type}:{target_key}'
        values = [{'text': text, 'priority': 100} for text in _normalized_natural_alias_expressions(expressions, target_id)]
        generated = {'target_type': target_type, 'target_key': target_key, 'values': values, **deepcopy(_NATURAL_ALIAS_POLICY)}
        if canonical_key in full_cards:
            full_cards[canonical_key] = _merge_natural_alias_card(full_cards[canonical_key], generated, canonical_key)
