            full_cards[canonical_key] = generated
        normalized_ids.append(canonical_key)
    current['aliases'] = {key: full_cards[key] for key in sorted(full_cards)}
    return (current, {'contract_version': 'metadata.alias-semantic-reconciliation.v1', 'resolution_mode': 'approved_semantic_vocabulary_exact', 'normalized_count': len(normalized_ids), 'normalized_alias_ids_sha256': sha256_json(sorted(normalized_ids))})

def _normalize_filter_operator_aliases(draft):
    """Canonicalize a small provider-independent filter vocabulary."""
    aliases = {'equals': 'eq', 'equal': 'eq', 'not_equals': 'ne', 'not_equal': 'ne', 'not_null': 'is_not_null', 'not_blank': 'is_not_blank', 'null': 'is_null', 'blank': 'is_blank', 'startswith': 'starts_with', 'endswith': 'ends_with', 'notin': 'not_in', 'greater_than': 'gt', 'greater_than_or_equal': 'gte', 'less_than': 'lt', 'less_than_or_equal': 'lte'}
    current = deepcopy(draft) if isinstance(draft, dict) else {}
    replacements = []

    def canonical(value):
        if not isinstance(value, str):
            return value
        token = re.sub('[\\s-]+', '_', value.strip().casefold())
        return aliases.get(token, value)

    def visit(value, path):
        if isinstance(value, list):
            for index, child in enumerate(value):
                visit(child, [*path, index])
            return
        if not isinstance(value, dict):
            return
        if 'operator' in value and 'field' in value:
            before = value.get('operator')
            after = canonical(before)
            if after != before:
                value['operator'] = after
                replacements.append({'path': [*path, 'operator'], 'canonical': after})
        for list_key in ('allowed_operators', 'allowed_filter_operators'):
            raw_items = value.get(list_key)
            if not isinstance(raw_items, list):
                continue
            normalized = [canonical(item) for item in raw_items]
            if normalized != raw_items:
                value[list_key] = normalized
                replacements.append({'path': [*path, list_key], 'canonical': normalized})
        for key, child in value.items():
            visit(child, [*path, str(key)])
    visit(current, [])
    return (current, {'contract_version': 'metadata.filter-operator-normalization.v1', 'replacement_count': len(replacements), 'replacements_sha256': sha256_json(replacements)})

