    if set(registry) != {'contract_version', 'domain_id', 'bindings', 'dataset_descriptors', 'semantic_vocabulary', 'semantic_templates', 'semantic_templates_sha256', 'semantic_templates_blueprint_sha256', 'semantic_templates_executable_sha256', 'semantic_templates_projection_sha256', 'registry_sha256'}:
