    registry_material = {'contract_version': registry.get('contract_version'), 'domain_id': registry.get('domain_id'), 'bindings': registry.get('bindings'), 'dataset_descriptors': registry.get('dataset_descriptors'), 'semantic_vocabulary': registry.get('semantic_vocabulary'), 'semantic_templates': registry.get('semantic_templates'), 'semantic_templates_sha256': registry.get('semantic_templates_sha256'), 'semantic_templates_blueprint_sha256': registry.get('semantic_templates_blueprint_sha256'), 'semantic_templates_executable_sha256': registry.get('semantic_templates_executable_sha256'), 'semantic_templates_projection_sha256': registry.get('semantic_templates_projection_sha256')}
