def _freeform_authoring_manifest(source_text):
    """Build hash-only source evidence without imposing syntax on a worker's TXT."""
    source_sha256 = hashlib.sha256(source_text.encode('utf-8')).hexdigest()
    inventories = {'datasets': [], 'dataset_fields': {}, 'fields': [], 'field_roles': {}, 'metrics': [], 'grains': [], 'grain_keys': {}, 'grain_display_fields': {}, 'relations': [], 'relation_endpoints': {}, 'relation_keys': {}, 'relation_policies': {}, 'recipes': [], 'operations': [], 'aliases': [], 'alias_targets': [], 'alias_bindings': []}
