def _freeform_dataset_patch_authorization_manifest(source_manifest, base_draft):
    """Authorize freeform Dataset patches only against the active base catalog.

    The worker's prose remains hash-only evidence and is never regex-parsed as
    a DSL.  This separate, sealed manifest is derived from already compiled
    metadata so an LLM may refer to existing dataset/field IDs but cannot mint
    a new target.  Source execution bindings remain controlled by the approved
    registry gate after patch application.
    """
    if not isinstance(source_manifest, dict) or not isinstance(base_draft, dict):
        raise ContractError('metadata_dependency_error', 'metadata_patch_authorization', '자유형 데이터셋 수정에 사용할 활성 메타데이터가 없습니다.')
    datasets = base_draft.get('datasets')
    if not isinstance(datasets, dict) or not datasets:
        raise ContractError('metadata_dependency_error', 'metadata_patch_authorization', '자유형 데이터셋 수정 대상 목록이 비어 있습니다.')
    authorization = deepcopy(source_manifest)
    inventories = deepcopy(authorization.get('inventories') or {})
    counts = deepcopy(authorization.get('counts') or {})
    dataset_ids = sorted((str(key) for key in datasets))
    dataset_fields = {}
    field_roles = {}
    for dataset_id in dataset_ids:
        dataset = datasets.get(dataset_id)
        fields = dataset.get('fields') if isinstance(dataset, dict) else None
        if not isinstance(fields, dict) or not fields:
            raise ContractError('metadata_dependency_error', 'metadata_patch_authorization', '활성 데이터셋의 field catalog가 비어 있습니다.', {'dataset_id_sha256': hashlib.sha256(dataset_id.encode('utf-8')).hexdigest()})
        field_ids = sorted((str(key) for key in fields))
        dataset_fields[dataset_id] = field_ids
        role_cards = {}
        for field_id in field_ids:
            field = fields.get(field_id)
            roles = field.get('roles') if isinstance(field, dict) else None
            if isinstance(roles, list) and roles:
                normalized_roles = [role for role in AUTHORING_FIELD_ROLE_ORDER if role in roles]
                if len(normalized_roles) != len(roles):
                    raise ContractError('metadata_dependency_error', 'metadata_patch_authorization', '활성 field role 계약이 유효하지 않습니다.', {'dataset_id_sha256': hashlib.sha256(dataset_id.encode('utf-8')).hexdigest(), 'field_id_sha256': hashlib.sha256(field_id.encode('utf-8')).hexdigest()})
                role_cards[field_id] = normalized_roles
        if role_cards:
            field_roles[dataset_id] = role_cards
    inventories['datasets'] = dataset_ids
    inventories['dataset_fields'] = dataset_fields
    inventories['fields'] = sorted({field_id for values in dataset_fields.values() for field_id in values})
    inventories['field_roles'] = field_roles
    counts['datasets'] = len(dataset_ids)
    counts['fields'] = len(inventories['fields'])
    counts['field_bindings'] = sum((len(values) for values in dataset_fields.values()))
    counts['field_roles'] = sum((len(values) for values in field_roles.values()))
    authorization['inventories'] = inventories
    authorization['counts'] = counts
    authorization.pop('manifest_sha256', None)
    authorization['manifest_sha256'] = sha256_json(authorization)
    return authorization

_AUTHORING_QUERY_MARKER = re.compile('(?im)^[ \\t]*(?:query_template|sql_template|oracle_sql|datalake_sql)[ \\t]*:[ \\t]*(?:\\n|$)')

_AUTHORING_QUERY_BLOCK_END = re.compile('(?im)^[ \\t]*(?:filter_mappings|required_params|required_param_mappings|standard_column_aliases|default_detail_columns|metric_semantics|selection_criteria)[ \\t]*(?:[:=]|(?:은|는)\\b)')

def _authoring_prompt_projected_source_text(value):
    text = str(value or '').replace('\r\n', '\n').replace('\r', '\n')
    markers = list(_AUTHORING_QUERY_MARKER.finditer(text))
    if not markers:
        return text
    pieces = []
    cursor = 0
    for index, marker in enumerate(markers):
        next_start = markers[index + 1].start() if index + 1 < len(markers) else len(text)
        boundary = _AUTHORING_QUERY_BLOCK_END.search(text, marker.end(), next_start)
        query_end = boundary.start() if boundary else next_start
        pieces.append(text[cursor:marker.end()])
        pieces.append('[SQL 원문은 결정론적 등록 컴파일러에서 별도 보존 및 검증됨]\n\n')
        cursor = query_end
    pieces.append(text[cursor:])
    return ''.join(pieces)

def _authoring_prompt_runtime_context_sha256(purpose, variables):
    projected = deepcopy(variables)
    if purpose == 'metadata_dataset_draft' and isinstance(projected.get('source_text'), str):
        projected['source_text'] = _authoring_prompt_projected_source_text(projected['source_text'])
    return sha256_json({'authority': 'untrusted_data', 'purpose': purpose, 'variables': projected})

def _bootstrap_context_payload(component, *, input_name, kind, purpose, domain_id, environment, bootstrap_fragment=True, grounding_mode='freeform_llm', annotation_only=False, expected_invoke=True):
