        raise ContractError('metadata_dependency_error', 'metadata_source_context', '분할 초기 등록의 승인 참조 컨텍스트 hash 또는 identity가 유효하지 않습니다.', {'input_name': input_name, 'authoring_branch': kind})
    expected_variable_keys = {'authoring_kind', 'domain_id', 'environment', 'source_grounding_mode', 'source_text', 'source_sha256', 'source_manifest', 'bootstrap_fragment', 'approved_semantic_vocabulary', 'source_registry_sha256'}
    context_invoke = context.get('invoke')
    if context_invoke is True:
        expected_variable_keys.add('output_schema')
    if annotation_only:
        expected_variable_keys.update({'default_annotations', 'blueprint_sha256'})
    if not isinstance(variables, dict) or set(variables) != expected_variable_keys:
        raise ContractError('metadata_dependency_error', 'metadata_source_context', '분할 초기 등록 runtime context variables 계약이 정확히 일치하지 않습니다.', {'input_name': input_name, 'authoring_branch': kind})
    source_text = variables.get('source_text')
    source_sha256 = variables.get('source_sha256')
