    registry_payload_valid = variables.get('approved_semantic_vocabulary') == expected_semantic_vocabulary and variables.get('source_registry_sha256') == expected_registry_sha256
    context_valid = context.get('contract_version') == 'prompt.runtime-context.v1' and context.get('purpose') == purpose and isinstance(context_invoke, bool) and (expected_invoke is None or context_invoke is expected_invoke) and (variables.get('authoring_kind') == kind) and (variables.get('domain_id') == domain_id) and (variables.get('environment') == environment) and (variables.get('source_grounding_mode') == grounding_mode) and (variables.get('bootstrap_fragment') is bool(bootstrap_fragment)) and (source_sha256 == expected_source_sha256) and (variables.get('source_manifest') == expected_manifest) and registry_payload_valid and (context_invoke is False or _bootstrap_schema_material(variables.get('output_schema')) == _bootstrap_schema_material(expected_output_schema))
    if not context_valid:
        raise ContractError('metadata_dependency_error', 'metadata_source_context', '분할 초기 등록 runtime context의 목적, 해시 또는 bootstrap 결합이 유효하지 않습니다.', {'input_name': input_name, 'authoring_branch': kind, 'expected_purpose': purpose, 'expected_source_sha256': expected_source_sha256})
    return {'source_text': source_text, 'source_sha256': expected_source_sha256, 'invoke': context_invoke, 'output_schema': deepcopy(variables['output_schema']) if context_invoke is True else None, 'output_schema_sha256': sha256_json(variables['output_schema']) if context_invoke is True else '', 'runtime_context_sha256': _authoring_prompt_runtime_context_sha256(purpose, variables)}

def _collection_authoring_context_payload(component, *, input_name, kind, purpose, domain_id, environment, grounding_mode):
    """Validate a simple authoring context without an external registry."""
    raw_context = getattr(component, input_name, None)
