    def _mongo(self):
        uri = _secret_text(getattr(self, 'mongo_uri', '')) or os.getenv('MONGODB_URI', '').strip()
        if not uri:
            raise ContractError('metadata_store_unavailable', 'metadata_store', 'MongoDB URI가 필요합니다.')
        from pymongo import MongoClient
        client = MongoClient(uri, serverSelectionTimeoutMS=max(500, min(int(getattr(self, 'mongo_timeout_ms', 5000)), 30000)))
        database = str(getattr(self, 'mongo_database', '') or os.getenv('MONGODB_DATABASE', 'datagov'))
        return (client, client[database])

    def _collection_names(self):
        values = {role: str(getattr(self, role, expected) or '').strip() for role, expected in V6_AUTHORING_COLLECTIONS.items()}
        invalid = [role for role, name in values.items() if re.fullmatch('[A-Za-z][A-Za-z0-9_.-]{0,127}', name) is None or name.casefold().startswith('system.')]
        if invalid or len(set(values.values())) != len(values):
            raise ContractError('metadata_policy_error', 'metadata_store_config', 'Metadata collection names must be safe and distinct.', {'invalid_roles': invalid, 'actual': values})
        return values

    def _response(self, status, *, stage, **values):
        material = {'contract_version': 'metadata.authoring.response.v1', 'response_type': 'metadata_authoring', 'status': status, 'stage': stage, 'authoring_kind': str(getattr(self, 'authoring_kind', 'domain')), 'metadata_contract_mode': str(getattr(self, 'metadata_contract_mode', 'domain_package_v2')), 'domain_id': str(getattr(self, 'domain_id', 'default')), 'environment': str(getattr(self, 'environment', 'production')), **values}
        material['response_sha256'] = sha256_json(material)
        return Data(data=validate_authoring_response_hash(material))

    def _save_initial_section_items(self, *, kind, raw_patch, source_text, source_manifest, authoring_proposal_validation, current_documents, collections, write_mode, dry_run, draft_llm_calls):
        """Store one collection-owned section before or after package completion."""
        source_binding_validation = {'contract_version': 'metadata.source-binding.validation.v1', 'status': 'not_applicable', 'binding_authority': 'metadata_three_collections'}
        source_query_extraction = {'contract_version': 'metadata.source-query-extraction.v1', 'status': 'not_applicable', 'query_count': 0, 'dataset_keys': [], 'datasets': {}, 'missing_query_dataset_keys': []}
        normalized_patch = deepcopy(raw_patch)
        if kind == 'domain':
            profile_keys = {'display_name', 'description', 'locale', 'timezone'}
            domain_item_sections = {'entity_groups', 'metrics', 'grains', 'relations', 'orderings', 'predicates', 'recipes'}
            is_profile_only = bool(profile_keys & set(normalized_patch)) and (not any((isinstance(normalized_patch.get(section), dict) for section in domain_item_sections)))
            if is_profile_only:
                normalized_patch['domain_id'] = str(getattr(self, 'domain_id', 'default') or 'default').strip()
        elif kind == 'dataset':
            partial_draft = {'datasets': deepcopy(raw_patch.get('datasets') or {})}
            source_binding_validation = _validate_authoring_source_bindings(partial_draft, source_sha256=str(source_manifest.get('source_sha256') or ''), proposal_sha256=str((authoring_proposal_validation or {}).get('proposal_sha256') or ''), approved_reference_context=getattr(self, 'approved_reference_context', None), domain_id=str(getattr(self, 'domain_id', '') or ''))
            partial_draft, source_query_extraction = apply_dataset_source_configs_from_text(partial_draft, source_text, require_complete=False)
            normalized_patch = {'datasets': partial_draft['datasets']}
        now = _bson_millisecond_utc(datetime.now(timezone.utc))
        candidate_items = make_partial_metadata_item_documents(kind, normalized_patch, source_text, updated_at=now.isoformat())
        merged_items, write_operations = merge_metadata_items_for_write(current_documents, candidate_items, mode=write_mode)
        conflict_count = int(write_operations.get('conflict_count') or 0)
        conflicts = list(write_operations.pop('conflicts', []))
        if conflict_count:
            raise ContractError('metadata_policy_error', 'metadata_duplicate', '기존 메타데이터와 중복되거나 어느 항목을 바꿀지 모호합니다. 표시된 canonical key를 확인해 주세요.', {'conflicts': conflicts, 'conflict_count': conflict_count, 'conflicts_truncated': bool(write_operations.get('conflicts_truncated'))})
        ready_sections = sorted((name for name, items in merged_items.items() if items))
        missing_sections = sorted((name for name, items in merged_items.items() if not items))
        package = None
        alias_activation = {'contract_version': 'metadata.alias-activation.v1', 'active_count': 0, 'deferred_count': 0, 'deferred': []}
        runtime_activation_issue = {}
        if not missing_sections:
            try:
                package = assemble_domain_package_from_items(merged_items, alias_activation_out=alias_activation)
                self.domain_id = str(package.get('domain_id') or getattr(self, 'domain_id', 'default'))
                validate_runtime_catalog_v2(package['runtime_catalog'])
            except ContractError as error:
                package = None
                runtime_activation_issue = {'code': str(error.code or 'metadata_dependency_error'), 'message': str(error.public_message or '전체 실행 메타데이터가 아직 준비되지 않았습니다.'), 'details': deepcopy(error.details or {})}
        validation = {'schema': 'passed', 'semantic_lint': 'passed' if package is not None else 'deferred', 'dependency_closure': 'passed' if package is not None else 'deferred', 'runtime_compile': 'passed' if package is not None else 'waiting_for_remaining_collections' if missing_sections else 'stored_runtime_pending', 'section_ownership': 'passed', 'three_collection_items': 'complete' if package is not None else 'partial', 'ready_sections': ready_sections, 'missing_sections': missing_sections, 'source_bindings': source_binding_validation, 'source_queries': source_query_extraction, 'runtime_alias_activation': alias_activation}
        if runtime_activation_issue:
            validation['runtime_activation_issue'] = runtime_activation_issue
        if authoring_proposal_validation is not None:
            validation['authoring_proposal'] = authoring_proposal_validation
        item_counts = {name: len(items) for name, items in merged_items.items()}
        validation['write_policy'] = {'mode': write_mode, 'identity': 'typed_item_identity', 'preserve_unmentioned': True, 'operations': deepcopy(write_operations)}
        candidate_hash = sha256_json({'contract_version': 'metadata.initial-section-candidate.v1', 'authoring_kind': kind, 'write_mode': write_mode, 'item_counts': item_counts, 'runtime_catalog_sha256': str(package['runtime_catalog'].get('catalog_sha256') or '') if package is not None else '', 'validation': validation})
        candidate_id = f'candidate:{candidate_hash}'
        if not dry_run:
            client, db = self._mongo()
            try:
                with client.start_session() as session:
                    with session.start_transaction():
                        transaction_documents = {'domain': _find_items(db[collections['domain_collection']], session=session), 'table_catalog': _find_items(db[collections['table_collection']], session=session), 'main_filter': _find_items(db[collections['main_filter_collection']], session=session)}
                        if metadata_item_set_projection(transaction_documents) != metadata_item_set_projection(current_documents):
                            raise ContractError('state_conflict', 'metadata_duplicate', '중복 확인 이후 기존 메타데이터가 변경되었습니다. 다시 실행해 주세요.', {'reason': 'concurrent_metadata_update'}, retryable=True)
                        if package is None:
                            upsert_partial_metadata_items(db, merged_items, session=session, domain_collection=collections['domain_collection'], table_collection=collections['table_collection'], main_filter_collection=collections['main_filter_collection'])
                        else:
                            replace_metadata_items(db, merged_items, session=session, domain_collection=collections['domain_collection'], table_collection=collections['table_collection'], main_filter_collection=collections['main_filter_collection'])
                            persisted = load_domain_package_from_three_collections(db, str(getattr(self, 'domain_id', '') or ''), str(getattr(self, 'environment', 'production') or 'production'), domain_collection=collections['domain_collection'], table_collection=collections['table_collection'], main_filter_collection=collections['main_filter_collection'], session=session)
                            if persisted['runtime_catalog'] != package['runtime_catalog']:
                                raise ContractError('metadata_hash_conflict', 'metadata_three_collection', '저장 후 다시 결합한 메타데이터 package가 컴파일 결과와 다릅니다.')
            finally:
                client.close()
        response_values = {'candidate_id': candidate_id, 'candidate_sha256': candidate_hash, 'revision': int((package or {}).get('revision') or 0), 'persisted': not dry_run, 'idempotent_replay': False, 'diff': {'authoring_kind': kind, 'write_mode': write_mode, 'write_operations': write_operations, 'item_counts': item_counts, 'activation_status': 'ready' if package is not None else 'waiting_for_sections' if missing_sections else 'stored_runtime_pending', 'ready_sections': ready_sections, 'missing_sections': missing_sections}, 'unchanged_section_checks': {}, 'validation': validation, 'llm_usage': {'draft_llm_calls': draft_llm_calls, 'annotation_llm_calls': 0, 'repair_llm_calls': 0}}
        if package is not None:
            response_values.update(package_sha256=package['package_sha256'], bundle_sha256=package['bundle_sha256'], catalog_sha256=package['runtime_catalog']['catalog_sha256'])
        return self._response('ok', stage='validated' if dry_run else 'committed', **response_values)

    def _prepare_v2(self):
        collections = self._collection_names()
        kind = str(getattr(self, 'authoring_kind', 'domain') or 'domain')
        if kind not in {'domain', 'dataset', 'main_filter', 'domain_policy'}:
            raise ContractError('metadata_schema_error', 'metadata_prepare', 'Unsupported v2 authoring kind.')
        domain_id = str(getattr(self, 'domain_id', 'default') or '').strip()
        environment = str(getattr(self, 'environment', 'production') or '').strip()
        grounding_mode = str(getattr(self, 'source_grounding_mode', 'freeform_llm') or 'freeform_llm').strip()
        if grounding_mode not in {'freeform_llm', 'explicit_inventory'}:
            raise ContractError('metadata_schema_error', 'metadata_source_grounding', 'source_grounding_mode must be freeform_llm or explicit_inventory.')
        blueprint_text = str(getattr(self, 'trusted_blueprint_json', '') or '').strip()
        trusted_blueprint_pin = str(getattr(self, 'trusted_blueprint_sha256', '') or '').strip()
        if kind == 'domain' and bool(blueprint_text) != bool(trusted_blueprint_pin):
            raise ContractError('metadata_blueprint_invalid', 'metadata_blueprint', 'Trusted blueprint JSON and its external SHA-256 pin must be configured together.')
        annotation_only = kind == 'domain' and bool(blueprint_text) and bool(trusted_blueprint_pin)
        split_bootstrap = bool(getattr(self, 'split_bootstrap', False))
        if split_bootstrap and (kind != 'domain' or grounding_mode != 'freeform_llm' or bool(blueprint_text) or bool(trusted_blueprint_pin)):
            raise ContractError('metadata_policy_error', 'metadata_authoring', '분할 초기 등록은 blueprint가 없는 domain/freeform_llm prepare에서만 사용할 수 있습니다.')
        bootstrap_branches = None
        section_context = None
        single_domain_bootstrap = False
        simple_section_bootstrap = False
        expected_purpose = {'domain': 'metadata_domain_annotation' if annotation_only else 'metadata_domain_draft', 'dataset': 'metadata_dataset_draft', 'main_filter': 'metadata_main_filter_draft', 'domain_policy': 'metadata_domain_policy'}[kind]
        if split_bootstrap:
            bootstrap_branches, source_text = _split_bootstrap_source(self, domain_id=domain_id, environment=environment)
        elif kind != 'domain_policy':
            raw_section_context = getattr(self, 'authoring_source_context', None)
            section_context_payload = getattr(raw_section_context, 'data', raw_section_context)
            if isinstance(section_context_payload, dict) and section_context_payload:
                raw_variables = section_context_payload.get('variables')
                simple_section_bootstrap = bool(isinstance(raw_variables, dict) and raw_variables.get('bootstrap_fragment') is True)
                single_domain_bootstrap = bool(kind == 'domain' and simple_section_bootstrap)
                raw_reference = getattr(self, 'approved_reference_context', None)
                reference_payload = getattr(raw_reference, 'data', raw_reference)
                if simple_section_bootstrap and (not reference_payload):
                    section_context = _collection_authoring_context_payload(self, input_name='authoring_source_context', kind=kind, purpose=expected_purpose, domain_id=domain_id, environment=environment, grounding_mode=grounding_mode)
                else:
                    section_context = _bootstrap_context_payload(self, input_name='authoring_source_context', kind=kind, purpose=expected_purpose, domain_id=domain_id, environment=environment, bootstrap_fragment=simple_section_bootstrap, grounding_mode=grounding_mode, annotation_only=annotation_only, expected_invoke=None)
                source_text = section_context['source_text']
            else:
                source_text = _authoring_source_text(self)
        else:
            source_text = _authoring_source_text(self)
        if not source_text or len(source_text.encode('utf-8')) > 65536:
            raise ContractError('metadata_schema_error', 'metadata_prepare', 'metadata TXT must contain 1 to 65536 UTF-8 bytes.')
        strict_inventory = grounding_mode == 'explicit_inventory' or annotation_only
        if strict_inventory:
            try:
                source_manifest = extract_authoring_source_manifest(source_text)
            except AuthoringSourceManifestError as exc:
                raise ContractError('metadata_dependency_error', 'metadata_source_inventory', 'Explicit-inventory metadata is ambiguous or invalid.', deepcopy(exc.evidence)) from exc
        else:
            source_manifest = _freeform_authoring_manifest(source_text)
        raw_reference_context = getattr(self, 'approved_reference_context', None)
        reference_context_payload = getattr(raw_reference_context, 'data', raw_reference_context)
        collection_owned_bootstrap = bool(simple_section_bootstrap and (not isinstance(reference_context_payload, dict))) or bool(simple_section_bootstrap and (not reference_context_payload))
        if kind == 'dataset' and strict_inventory:
            inventories = source_manifest.get('inventories')
            datasets = inventories.get('datasets') if isinstance(inventories, dict) else None
            dataset_fields = inventories.get('dataset_fields') if isinstance(inventories, dict) else None
            valid_dataset_inventory = isinstance(datasets, list) and bool(datasets) and isinstance(dataset_fields, dict) and (set(dataset_fields) == set(datasets)) and all((isinstance(dataset_fields.get(dataset_id), list) and bool(dataset_fields[dataset_id]) for dataset_id in datasets))
