from copy import deepcopy

from lfx.custom.custom_component.component import Component
from lfx.io import DataInput, Output
from lfx.schema.message import Message


class AuthoringMessagePresentation(Component):
    display_name = "메타데이터 등록 메시지 구성"
    description = "저장·검증·추가 확인 결과를 짧은 한글 메시지로 표시하고 canonical response를 data에 보존합니다."
    icon = "file-check-2"

    inputs = [DataInput(name="response", display_name="메타데이터 등록 응답", required=True, info="저장 완료, 검증 완료, 추가 확인 필요, 오류 중 하나의 표준 등록 응답입니다.")]
    outputs = [Output(name="message", display_name="등록 결과 채팅 메시지", method="build_message", types=["Message"])]

    def build_message(self) -> Message:
        raw = getattr(getattr(self, "response", None), "data", getattr(self, "response", None))
        # Contract validation is complete in the preceding authoring engine.
        # Langflow 1.10.x may inject UI/runtime fields such as ``default_value``
        # while transporting Data between nodes, so this presentation-only
        # boundary deliberately accepts ordinary JSON and removes only those
        # transport fields instead of revalidating the sealed engine payload.
        response = deepcopy(raw) if isinstance(raw, dict) else {}
        response.pop("default_value", None)
        diff = response.get("diff") if isinstance(response.get("diff"), dict) else {}
        # Node 04 now exposes a compact worker-facing response.  Keep support
        # for the older internal response shape so previously exported flows
        # can still feed this presentation node during a rolling upgrade.
        operations = (
            diff.get("write_operations")
            if isinstance(diff.get("write_operations"), dict)
            else diff
        )
        operation_summary = (
            f"- 처리 결과: 신규 {int(operations.get('inserted') or 0)} / "
            f"교체 {int(operations.get('replaced') or 0)} / "
            f"동일 {int(operations.get('unchanged') or 0)}"
        )
        if response.get("status") == "ok" and response.get("stage") == "validated":
            text = "### 메타데이터 검증 완료\n\n" + f"- Revision: {response.get('revision', '')}\n{operation_summary}\n- MongoDB 저장: 안 함"
        elif response.get("status") == "ok":
            activation_status = str(diff.get("activation_status") or "ready")
            if activation_status == "waiting_for_sections":
                ready_sections = ", ".join(str(value) for value in diff.get("ready_sections") or []) or "없음"
                missing_sections = ", ".join(str(value) for value in diff.get("missing_sections") or []) or "없음"
                text = (
                    "### 메타데이터 항목 저장 완료 (실행 준비 중)\n\n"
                    + f"{operation_summary}\n- 등록 완료 영역: {ready_sections}\n"
                    + f"- 추가 등록 필요 영역: {missing_sections}\n"
                    + "- 세 영역이 모두 등록되면 자동으로 전체 실행 메타데이터를 검증합니다."
                )
            elif activation_status == "stored_runtime_pending":
                text = (
                    "### 메타데이터 항목 저장 완료 (실행 활성화 대기)\n\n"
                    + f"{operation_summary}\n"
                    + "- 이번 입력 항목의 구조 및 중복 검증: 통과\n"
                    + "- 기존 전체 메타데이터 실행 점검: 대기"
                )
            else:
                text = (
                    "### 메타데이터 저장 완료\n\n"
                    + f"- Revision: {response.get('revision', '')}\n{operation_summary}"
                    + "\n- 저장 구조: 도메인·테이블 카탈로그·메인필터"
                    + "\n- 실행 메타데이터: 사용 가능"
                )
        elif response.get("status") == "needs_clarification":
            clarification = response.get("clarification") if isinstance(response.get("clarification"), dict) else {}
            questions = [str(item) for item in (clarification.get("questions") or [])[:3]]
            text = "### 메타데이터 등록 전 확인이 필요합니다\n\n" + "\n".join(
                f"{index}. {question}" for index, question in enumerate(questions, 1)
            )
        else:
            error = response.get("error") if isinstance(response.get("error"), dict) else {}
            text = "### 메타데이터 등록 실패\n\n" + f"- Code: `{error.get('code', 'metadata_authoring_failed')}`\n- Message: {error.get('message', '')}"
            details = error.get("details") if isinstance(error.get("details"), dict) else {}
            conflicts = details.get("conflicts") if isinstance(details.get("conflicts"), list) else []
            conflict_lines = []
            for item in conflicts[:3]:
                if not isinstance(item, dict):
                    continue
                candidates = item.get("duplicate_candidates") if isinstance(item.get("duplicate_candidates"), list) else []
                candidate_keys = ", ".join(
                    str(candidate.get("key") or "")
                    for candidate in candidates[:3]
                    if isinstance(candidate, dict) and str(candidate.get("key") or "")
                )
                suffix = f" → 기존 후보 {candidate_keys}" if candidate_keys else ""
                conflict_lines.append(
                    f"- 중복 확인: {item.get('collection', '')}/{item.get('section', '')}/{item.get('key', '')} "
                    f"({item.get('reason', '')}){suffix}"
                )
            if conflict_lines:
                text += "\n" + "\n".join(conflict_lines)
        message = Message(
            text=text,
            sender="Machine",
            sender_name="Metadata Authoring",
            session_metadata={
                "contract_version": "metadata.authoring.message-link.v1",
            },
        )
        message.data = {"response": response}
        return message
